css:
/* ==========================================================================
   LIFE · CLIENT - 360 · v8.0 — paste into Web Page › Style › CSS
   Replaces all previous CSS layers (V1…V22). Scoped to #c360App.
   ========================================================================== */
@import url("https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap");

/* ---------- page shell ---------- */
body.c360-page { background: #F3F6F3 !important; margin: 0 !important; overflow-x: hidden; }
body.c360-page .web-page-content, body.c360-page .page_content, body.c360-page main,
body.c360-page .web-page-content > .container, body.c360-page .page_content > .container, body.c360-page main > .container {
  width: 100% !important; max-width: 100% !important; margin: 0 !important; padding: 0 !important;
}

#c360App {
  --g950: #0B2E1C; --g900: #0E3B24; --g800: #134B2E; --g700: #17603A; --g600: #1F7A49; --g500: #2E9460;
  --teal: #0F766E; --mint: #EEF6F0; --mint2: #E1EEE5; --paper: #FFFFFF; --canvas: #F3F6F3;
  --ink: #1C2821; --ink2: #44544A; --mute: #76847B; --line: #DCE6DE; --line2: #EBF1EC;
  --ok: #15803D;  --ok-bg: #E6F4EA;  --ok-line: #B9DEC5;
  --warn: #B45309; --warn-bg: #FDF1E0; --warn-line: #F2D2A8;
  --neg: #B42318; --neg-bg: #FDEBE9; --neg-line: #F2C1BB;
  --info: #1D4ED8; --info-bg: #E9EFFD; --info-line: #C5D4F7;
  --purple: #6D28D9; --purple-bg: #F1EAFD; --purple-line: #D7C6F5;
  --amber: #A16207; --amber-bg: #FDF6DB; --amber-line: #EEDC9C;
  --slate: #475569; --slate-bg: #EFF2F5; --slate-line: #D3DAE2;
  --r-lg: 18px; --r: 12px; --r-sm: 8px; --r-xs: 6px;
  --shadow: 0 1px 2px rgba(14,59,36,.05), 0 6px 18px rgba(14,59,36,.05);
  --shadow-lg: 0 30px 80px rgba(6,40,22,.28);
  box-sizing: border-box;
  width: calc(100vw - 28px); max-width: 1780px; margin: 14px auto 40px;
  font-family: "Plus Jakarta Sans", "Segoe UI", system-ui, sans-serif;
  font-size: 14px; line-height: 1.45; color: var(--ink);
  font-variant-numeric: tabular-nums;
  -webkit-font-smoothing: antialiased;
}
#c360App *, #c360App *::before, #c360App *::after { box-sizing: border-box; }
#c360App button, #c360App input, #c360App select, #c360App textarea { font: inherit; color: inherit; }
#c360App h1, #c360App h2, #c360App h3, #c360App h4, #c360App h5, #c360App p { margin: 0; }
#c360App a { color: var(--g700); }
#c360App [hidden] { display: none !important; }
#c360App :focus-visible { outline: 2px solid var(--g500); outline-offset: 2px; }
#c360App .t-r { text-align: right; } #c360App .t-c { text-align: center; }

/* semantic text colours (zero specificity; containers override) */
#c360App :where(.tone-ok) { color: var(--ok); }
#c360App :where(.tone-warn) { color: var(--warn); }
#c360App :where(.tone-neg) { color: var(--neg); }
#c360App :where(.tone-info) { color: var(--info); }
#c360App :where(.tone-mute) { color: var(--mute); }
#c360App :where(.tone-purple) { color: var(--purple); }
#c360App :where(.tone-amber) { color: var(--amber); }
#c360App :where(.tone-blue) { color: var(--info); }

/* ---------- buttons ---------- */
#c360App .c3-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px;
  min-height: 38px; padding: 0 14px; border: 1px solid var(--line); border-radius: var(--r-sm);
  background: var(--paper); color: var(--ink2); font-size: 13px; font-weight: 700; white-space: nowrap;
  cursor: pointer; text-decoration: none; transition: background .15s, border-color .15s, box-shadow .15s;
}
#c360App .c3-btn:hover { border-color: #B8CFBF; background: var(--mint); color: var(--g800); text-decoration: none; }
#c360App .c3-btn:disabled { opacity: .45; cursor: not-allowed; }
#c360App .c3-btn-sm { min-height: 32px; padding: 0 10px; font-size: 12px; }
#c360App .c3-btn-primary { background: var(--g700); border-color: var(--g700); color: #fff; }
#c360App .c3-btn-primary:hover { background: var(--g800); border-color: var(--g800); color: #fff; }
#c360App .c3-btn-danger { color: var(--neg); border-color: var(--neg-line); background: #FFF8F7; }
#c360App .c3-btn-danger.is-on { background: var(--neg); border-color: var(--neg); color: #fff; }
#c360App .c3-btn-light { background: #fff; border-color: rgba(255,255,255,.6); color: var(--g800); }
#c360App .c3-btn-ghost { background: rgba(255,255,255,.1); border-color: rgba(255,255,255,.35); color: #fff; }
#c360App .c3-btn-ghost:hover { background: rgba(255,255,255,.2); color: #fff; }
#c360App .c3-btn-wa { background: #128C4B; border-color: #128C4B; color: #fff; }
#c360App .c3-btn-wa:hover { background: #0E7340; color: #fff; }
#c360App .c3-close {
  width: 38px; height: 38px; border-radius: 50%; border: 1px solid rgba(255,255,255,.35);
  background: rgba(255,255,255,.12); color: #fff; font-size: 15px; cursor: pointer; flex: none;
}
#c360App .c3-drawer .c3-close { border-color: var(--line); background: var(--mint); color: var(--ink2); }

/* ---------- masthead ---------- */
#c360App .c3-mast {
  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;
  padding: 18px 24px; border-radius: var(--r-lg) var(--r-lg) 0 0;
  background: var(--g900); color: #fff;
  background-image: radial-gradient(circle at 92% -40%, rgba(46,148,96,.45), transparent 55%);
}
#c360App .c3-mast-brand { display: flex; align-items: center; gap: 14px; min-width: 0; }
#c360App .c3-brand {
  display: inline-flex; align-items: center; padding: 6px 10px; border-radius: 9px;
  background: #D9F2E1; color: var(--g800); font-weight: 800; font-size: 13px; letter-spacing: 1.5px;
}
#c360App .c3-mast h1 { font-size: 26px; font-weight: 800; letter-spacing: .5px; line-height: 1.1; }
#c360App .c3-mast p { margin-top: 3px; color: #B9D8C4; font-size: 13px; }
#c360App .c3-mast-actions { display: flex; align-items: center; gap: 10px; }
#c360App .c3-count-pill { padding: 8px 14px; border-radius: 999px; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.2); font-size: 13px; }
#c360App .c3-count-pill b { font-size: 16px; }

/* ---------- filters ---------- */
#c360App .c3-filters-panel {
  position: sticky; top: 0; z-index: 40;
  display: grid; gap: 10px; padding: 14px 24px 12px;
  background: rgba(255,255,255,.97); backdrop-filter: blur(8px);
  border: 1px solid var(--line); border-top: 0; border-radius: 0 0 var(--r-lg) var(--r-lg);
  box-shadow: var(--shadow);
}
#c360App .c3-frow { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
#c360App .c3-search, #c360App .c3-sel {
  position: relative; display: flex; align-items: center; gap: 8px; min-height: 40px; padding: 0 10px;
  border: 1px solid var(--line); border-radius: var(--r-sm); background: #FBFCFB;
}
#c360App .c3-search { flex: 1 1 320px; min-width: 240px; }
#c360App .c3-sel { flex: 0 1 200px; }
#c360App .c3-search:focus-within, #c360App .c3-sel:focus-within { border-color: var(--g500); background: #fff; box-shadow: 0 0 0 3px rgba(46,148,96,.12); }
#c360App .c3-search input, #c360App .c3-sel select {
  flex: 1; min-width: 0; height: 38px; border: 0 !important; outline: 0; background: transparent !important; box-shadow: none !important; padding: 0; font-size: 14px;
}
#c360App .c3-x { border: 0; background: var(--mint); width: 26px; height: 26px; border-radius: 50%; cursor: pointer; color: var(--mute); }
#c360App .c3-flabel { font-size: 13px; font-weight: 700; color: var(--ink2); }
#c360App .c3-date, #c360App .c3-input {
  min-height: 38px; padding: 6px 10px; border: 1px solid var(--line); border-radius: var(--r-sm); background: #fff; font-size: 13px; outline: 0; box-shadow: none;
}
#c360App .c3-input:focus, #c360App .c3-date:focus { border-color: var(--g500); box-shadow: 0 0 0 3px rgba(46,148,96,.12); }
#c360App .c3-arrow { color: var(--mute); }
#c360App .c3-quick { display: flex; gap: 4px; flex-wrap: wrap; padding: 3px; background: var(--mint); border-radius: 10px; }
#c360App .c3-q { border: 0; background: transparent; padding: 7px 12px; border-radius: 7px; font-size: 13px; font-weight: 600; color: var(--ink2); cursor: pointer; }
#c360App .c3-q:hover { background: #fff; }
#c360App .c3-q.is-on { background: var(--g700); color: #fff; box-shadow: 0 2px 6px rgba(23,96,58,.25); }
#c360App .c3-statusbar { font-size: 13px; color: var(--mute); }
#c360App .c3-statusbar b { color: var(--g700); }

/* lookup */
#c360App .c3-lookup {
  position: absolute; top: calc(100% + 6px); left: 0; z-index: 60; width: min(720px, calc(100vw - 40px));
  max-height: 440px; overflow: auto; padding: 8px; background: #fff;
  border: 1px solid var(--line); border-radius: var(--r); box-shadow: 0 20px 50px rgba(14,59,36,.2);
}
#c360App .c3-look-h { padding: 4px 8px 8px; font-size: 12px; font-weight: 700; color: var(--mute); }
#c360App .c3-look-state { padding: 18px; text-align: center; color: var(--mute); font-size: 13px; }
#c360App .c3-look-item { display: grid; grid-template-columns: 30px minmax(0,1fr) auto; gap: 10px; align-items: center; padding: 10px; border-radius: var(--r-sm); }
#c360App .c3-look-item + .c3-look-item { border-top: 1px solid var(--line2); }
#c360App .c3-look-item:hover { background: var(--mint); }
#c360App .c3-look-main b { display: block; font-size: 14px; color: var(--g900); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#c360App .c3-look-meta { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 3px; }
#c360App .c3-look-act { display: flex; gap: 6px; }

/* ---------- phone masking ---------- */
#c360App .c3-phone {
  position: relative; display: inline-flex; align-items: center; gap: 5px; padding: 2px 8px;
  border-radius: 999px; background: var(--mint); border: 1px solid var(--line2);
  font-size: 12px; font-weight: 600; color: var(--ink2); cursor: default; white-space: nowrap;
}
#c360App .c3-phone em { font-style: normal; color: var(--mute); font-weight: 500; }
#c360App .c3-phone-f { display: none; }
#c360App .c3-phone:hover .c3-phone-m, #c360App .c3-phone:focus .c3-phone-m { display: none; }
#c360App .c3-phone:hover .c3-phone-f, #c360App .c3-phone:focus .c3-phone-f { display: inline; color: var(--g800); }
#c360App .c3-phone:hover, #c360App .c3-phone:focus { background: #fff; border-color: var(--ok-line); }
#c360App .c3-hero .c3-phone { background: rgba(255,255,255,.12); border-color: rgba(255,255,255,.25); color: #E6F3EA; }
#c360App .c3-hero .c3-phone:hover .c3-phone-f, #c360App .c3-hero .c3-phone:focus .c3-phone-f { color: var(--g900); }

/* ---------- pills & chips ---------- */
#c360App .c3-pill {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px; border-radius: 999px;
  font-size: 12px; font-weight: 700; line-height: 1.35; white-space: nowrap;
  background: var(--slate-bg); color: var(--slate); border: 1px solid var(--slate-line);
}
#c360App .c3-pill.tone-ok { background: var(--ok-bg); color: var(--ok); border-color: var(--ok-line); }
#c360App .c3-pill.tone-warn { background: var(--warn-bg); color: var(--warn); border-color: var(--warn-line); }
#c360App .c3-pill.tone-neg { background: var(--neg-bg); color: var(--neg); border-color: var(--neg-line); }
#c360App .c3-pill.tone-info, #c360App .c3-pill.tone-blue { background: var(--info-bg); color: var(--info); border-color: var(--info-line); }
#c360App .c3-pill.tone-purple { background: var(--purple-bg); color: var(--purple); border-color: var(--purple-line); }
#c360App .c3-pill.tone-amber { background: var(--amber-bg); color: var(--amber); border-color: var(--amber-line); }
#c360App .c3-pill.tone-mute { background: var(--slate-bg); color: var(--slate); border-color: var(--slate-line); }
#c360App .c3-chip {
  display: inline-flex; align-items: center; gap: 4px; padding: 3px 9px; border-radius: var(--r-xs);
  background: var(--mint); border: 1px solid var(--line2); font-size: 12px; font-weight: 600; color: var(--ink2); white-space: nowrap;
}
#c360App .c3-chip.tone-warn { background: var(--warn-bg); border-color: var(--warn-line); color: var(--warn); }
#c360App .c3-chip.tone-neg { background: var(--neg-bg); border-color: var(--neg-line); color: var(--neg); }
#c360App .c3-chip-btn { cursor: pointer; }
#c360App .c3-chips { display: flex; flex-wrap: wrap; gap: 6px; }
#c360App .c3-g { font-size: 18px; line-height: 1; }
#c360App .c3-mini { font-size: 12px; font-weight: 600; color: var(--ink2); margin-top: 4px; }
#c360App .c3-note { font-size: 12px; color: var(--mute); }
#c360App .c3-blink { animation: c3pulse 2.2s ease-in-out infinite; }
@keyframes c3pulse { 50% { box-shadow: 0 0 0 5px rgba(180,35,24,.18); } }

/* ---------- KPI strip ---------- */
#c360App .c3-kpi-strip { display: grid; grid-template-columns: repeat(5, minmax(0,1fr)); gap: 12px; margin: 14px 0; }
#c360App .c3-kpi-card {
  display: grid; gap: 4px; padding: 14px 16px; background: var(--paper); border: 1px solid var(--line);
  border-radius: var(--r); box-shadow: var(--shadow); color: var(--ink); min-width: 0;
}
#c360App .c3-kpi-card small { font-size: 12px; font-weight: 700; color: var(--mute); }
#c360App .c3-kpi-v { font-size: 26px; font-weight: 800; letter-spacing: -.5px; line-height: 1.15; color: var(--g900); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
#c360App .c3-kpi-v.tone-ok { color: var(--ok); } #c360App .c3-kpi-v.tone-warn { color: var(--warn); }
#c360App .c3-kpi-v.tone-neg { color: var(--neg); } #c360App .c3-kpi-v.tone-info { color: var(--info); }
#c360App .c3-kpi-hint { font-size: 12px; color: var(--mute); }
#c360App .c3-kpi-hint.tone-neg { color: var(--neg); font-weight: 600; } #c360App .c3-kpi-hint.tone-ok { color: var(--ok); }
#c360App .c3-kpi-out { border-color: var(--neg-line); background: linear-gradient(180deg, #FFF9F8, #fff 60%); }

/* ---------- table ---------- */
#c360App .c3-table-card { background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); overflow: hidden; }
#c360App .c3-table-scroll { overflow-x: auto; }
#c360App .c3-table { width: 100%; min-width: 1200px; border-collapse: collapse; }
#c360App .c3-table th {
  position: sticky; top: 0; padding: 11px 12px; background: #F4F8F5; border-bottom: 1px solid var(--line);
  font-size: 12px; font-weight: 700; color: var(--ink2); text-align: left; white-space: nowrap;
}
#c360App .c3-table td { padding: 11px 12px; border-bottom: 1px solid var(--line2); font-size: 13px; vertical-align: middle; white-space: nowrap; }
#c360App .c3-row { cursor: pointer; transition: background .12s; }
#c360App .c3-row:hover td { background: #F5FAF6; }
#c360App .c3-row.is-overdue td:first-child { box-shadow: inset 3px 0 0 var(--neg); }
#c360App .c3-row.is-due td:first-child { box-shadow: inset 3px 0 0 var(--warn); }
#c360App .c3-num-cell { color: var(--mute); width: 40px; }
#c360App .c3-client-cell { display: flex; align-items: center; gap: 10px; }
#c360App .c3-client-name { display: block; padding: 0; border: 0; background: none; font-size: 14px; font-weight: 700; color: var(--g800); cursor: pointer; margin-bottom: 3px; text-align: left; }
#c360App .c3-client-name:hover { text-decoration: underline; }
#c360App .c3-count { display: inline-flex; min-width: 32px; justify-content: center; padding: 3px 8px; border-radius: 999px; background: var(--mint); font-weight: 700; color: var(--g700); }
#c360App .c3-money { font-weight: 700; }
#c360App .c3-sticky { position: sticky; right: 0; background: var(--paper); box-shadow: -6px 0 10px -8px rgba(14,59,36,.2); }
#c360App thead .c3-sticky { background: #F4F8F5; }
#c360App .c3-row:hover .c3-sticky { background: #F5FAF6; }
#c360App .c3-inv-btn { display: inline-flex; gap: 6px; align-items: center; padding: 5px 11px; border-radius: var(--r-sm); border: 1px solid var(--info-line); background: var(--info-bg); color: var(--info); cursor: pointer; font-size: 13px; }
#c360App .c3-inv-btn.has-due { border-color: var(--neg-line); background: var(--neg-bg); color: var(--neg); }
#c360App .c3-state { padding: 60px 20px !important; text-align: center; color: var(--mute); white-space: normal !important; }
#c360App .c3-state p { margin-top: 10px; font-size: 14px; color: var(--ink2); font-weight: 600; }
#c360App .c3-state small { color: var(--mute); }
#c360App .c3-state-ic { font-size: 34px; }
#c360App .c3-pager { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; padding: 10px 14px; border-top: 1px solid var(--line2); font-size: 13px; color: var(--mute); }
#c360App .c3-pager-btns, #c360App .c3-pagenums { display: flex; align-items: center; gap: 4px; }
#c360App .c3-pg { min-width: 32px; height: 32px; border-radius: var(--r-sm); border: 1px solid var(--line); background: #fff; cursor: pointer; font-size: 13px; }
#c360App .c3-pg.is-on { background: var(--g700); border-color: var(--g700); color: #fff; }
#c360App .c3-dots { color: var(--mute); padding: 0 3px; }
#c360App .c3-hint-line { margin: 10px 4px 18px; font-size: 12px; color: var(--mute); }

/* LIFE loader */
#c360App .c3-loader { display: inline-grid; place-items: center; width: 52px; height: 52px; border-radius: 50%; background: conic-gradient(var(--g500) 0 25%, var(--mint2) 25% 100%); animation: c3spin 1s linear infinite; }
#c360App .c3-loader span { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%; background: #fff; font-size: 10px; font-weight: 800; letter-spacing: 1px; color: var(--g700); animation: c3spin 1s linear infinite reverse; }
#c360App .c3-spin { display: inline-block; width: 14px; height: 14px; border: 2px solid var(--mint2); border-top-color: var(--g600); border-radius: 50%; animation: c3spin .7s linear infinite; vertical-align: -2px; }
@keyframes c3spin { to { transform: rotate(360deg); } }

/* ---------- network dashboard ---------- */
#c360App .c3-dash { background: var(--paper); border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); }
#c360App .c3-dash-h { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 10px 14px; border-bottom: 1px solid var(--line2); }
#c360App .c3-dash-toggle { display: flex; align-items: center; gap: 10px; border: 0; background: none; font-size: 16px; font-weight: 800; color: var(--g900); cursor: pointer; }
#c360App .c3-dash-tools { display: flex; align-items: center; gap: 10px; }
#c360App .c3-chev { display: inline-block; transition: transform .2s; }
#c360App .c3-dash.is-collapsed .c3-dash-b { display: none; }
#c360App .c3-dash.is-collapsed .c3-chev { transform: rotate(180deg); }
#c360App .c3-dash-b { padding: 14px; }
#c360App .c3-dgrid { display: grid; grid-template-columns: repeat(auto-fill, minmax(200px, 1fr)); gap: 10px; }
#c360App .c3-dcard {
  display: flex; align-items: center; gap: 12px; padding: 12px; text-align: left; border: 1px solid var(--line2);
  border-left: 4px solid var(--g500); border-radius: var(--r-sm); background: #FBFCFB; color: var(--ink); cursor: default;
}
#c360App button.c3-dcard { cursor: pointer; }
#c360App button.c3-dcard:hover { background: var(--mint); }
#c360App .c3-dcard.tone-ok { border-left-color: var(--ok); } #c360App .c3-dcard.tone-warn { border-left-color: var(--warn); }
#c360App .c3-dcard.tone-neg { border-left-color: var(--neg); } #c360App .c3-dcard.tone-info { border-left-color: var(--info); }
#c360App .c3-dc-ic { font-size: 22px; }
#c360App .c3-dcard b { display: block; font-size: 22px; font-weight: 800; color: var(--g900); line-height: 1.1; }
#c360App .c3-dcard b.c3-sm { font-size: 15px; }
#c360App .c3-dcard small { display: block; font-size: 13px; font-weight: 700; color: var(--ink2); }
#c360App .c3-dcard em { display: block; font-style: normal; font-size: 12px; color: var(--mute); }
#c360App .c3-dlists { display: grid; grid-template-columns: repeat(3, minmax(0,1fr)); gap: 12px; margin-top: 12px; }
#c360App .c3-dlist { padding: 12px; border: 1px solid var(--line2); border-radius: var(--r-sm); }
#c360App .c3-dlist h4 { font-size: 14px; font-weight: 700; margin-bottom: 8px; }
#c360App .c3-bars { display: grid; gap: 7px; }
