#c360App .c3-tl-d { font-size: 12px; color: var(--mute); font-weight: 600; }
#c360App .c3-tl-e { font-size: 16px; }
#c360App .c3-timeline b { display: block; font-size: 13px; font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#c360App .c3-timeline em { font-style: normal; font-size: 12px; color: var(--mute); }
#c360App .c3-ref-list { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 10px; }

/* KPI rows inside tabs */
#c360App .c3-kpis { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; margin-bottom: 14px; }
#c360App .c3-kpi { display: flex; align-items: center; gap: 10px; padding: 11px 13px; background: #fff; border: 1px solid var(--line); border-radius: var(--r-sm); color: var(--ink); }
#c360App .c3-kpi-ic { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 10px; background: var(--mint); font-size: 18px; flex: none; }
#c360App .c3-kpi small { display: block; font-size: 12px; font-weight: 600; color: var(--mute); }
#c360App .c3-kpi b { font-size: 20px; font-weight: 800; color: var(--g900); }
#c360App .c3-kpi b.tone-ok { color: var(--ok); } #c360App .c3-kpi b.tone-warn { color: var(--warn); }
#c360App .c3-kpi b.tone-neg { color: var(--neg); } #c360App .c3-kpi b.tone-info { color: var(--info); }

/* cards */
#c360App .c3-cards { display: grid; gap: 12px; align-items: start; }
#c360App .c3-c1 { grid-template-columns: 1fr; }
#c360App .c3-c2 { grid-template-columns: repeat(2, minmax(0,1fr)); }
#c360App .c3-c4 { grid-template-columns: repeat(4, minmax(0,1fr)); }
#c360App .c3-card { display: grid; gap: 8px; min-width: 0; padding: 13px; background: #fff; border: 1px solid var(--line); border-radius: var(--r); box-shadow: var(--shadow); color: var(--ink); }
#c360App .c3-accent { border-top: 4px solid var(--ok); }
#c360App .c3-accent.tone-warn { border-top-color: #E8A33D; } #c360App .c3-accent.tone-neg { border-top-color: var(--neg); }
#c360App .c3-accent.tone-info { border-top-color: var(--info); } #c360App .c3-accent.tone-mute { border-top-color: #A3B0A8; }
#c360App .c3-card-h { display: flex; justify-content: space-between; align-items: flex-start; gap: 8px; }
#c360App .c3-card-h > div { min-width: 0; }
#c360App .c3-card-h b { display: block; font-size: 15px; font-weight: 800; color: var(--g900); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#c360App .c3-card-h small { display: block; font-size: 12px; color: var(--mute); margin-top: 2px; }
#c360App .c3-therapies { display: grid; gap: 6px; }
#c360App .c3-th { display: grid; grid-template-columns: minmax(0,1fr) auto auto; gap: 4px 12px; align-items: center; padding: 8px 10px; background: #F8FAF8; border-radius: var(--r-sm); font-size: 13px; }
#c360App .c3-th b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#c360App .c3-th .c3-meter { grid-column: 1 / -1; margin: 0; height: 5px; }

/* coloured fields (sessions / appointments) */
#c360App .c3-field { min-width: 0; padding: 8px 10px; border-radius: var(--r-sm); background: #F8FAF8; border: 1px solid var(--line2); border-left: 4px solid #C6D3CA; }
#c360App .c3-field small { display: block; font-size: 11px; font-weight: 700; color: var(--mute); }
#c360App .c3-field b { display: block; font-size: 14px; font-weight: 700; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#c360App .f-green { border-left-color: #2E9460; background: #EFF8F2; } #c360App .f-green b { color: #14633A; }
#c360App .f-blue { border-left-color: #3B82F6; background: #EFF5FF; } #c360App .f-blue b { color: #1E4FA8; }
#c360App .f-amber { border-left-color: #D99B17; background: #FFF8E6; } #c360App .f-amber b { color: #7C560A; }
#c360App .f-purple { border-left-color: #8B5CC7; background: #F5EFFF; } #c360App .f-purple b { color: #5B2E99; }
#c360App .f-teal { border-left-color: #14908A; background: #EAF8F6; } #c360App .f-teal b { color: #0E6560; }
#c360App .f-rose { border-left-color: #D75858; background: #FFF2F2; }

/* followups */
#c360App .c3-fu { border-left: 5px solid #94A3B8; }
#c360App .c3-fu.f-blue { border-left-color: #3B82F6; } #c360App .c3-fu.f-green { border-left-color: #22A447; }
#c360App .c3-fu.f-orange { border-left-color: #F59E0B; } #c360App .c3-fu.f-amber { border-left-color: #EAB308; }
#c360App .c3-fu.f-red { border-left-color: #DC2626; } #c360App .c3-fu.f-teal { border-left-color: #0D9488; }
#c360App .c3-fu.f-purple { border-left-color: #7C3AED; } #c360App .c3-fu.f-slate { border-left-color: #64748B; }
#c360App .c3-fu { background: #fff; }
#c360App .c3-fu.is-late { box-shadow: 0 0 0 1px var(--neg-line), var(--shadow); }
#c360App .c3-fu-type { background: var(--mint) !important; color: var(--g800) !important; border-color: var(--line2) !important; margin-bottom: 3px; }
#c360App .c3-fu-remark { padding: 9px 11px; border-radius: var(--r-sm); background: #F4F8F5; border-left: 3px solid var(--g500); font-size: 14px; line-height: 1.55; white-space: pre-wrap; }
#c360App .c3-fu-resp { padding: 8px 11px; border-radius: var(--r-sm); background: var(--info-bg); font-size: 13px; color: #1E3A8A; }
#c360App .c3-fbtn.f-blue { border-left: 3px solid #3B82F6; } #c360App .c3-fbtn.f-green { border-left: 3px solid #22A447; }
#c360App .c3-fbtn.f-orange { border-left: 3px solid #F59E0B; } #c360App .c3-fbtn.f-red { border-left: 3px solid #DC2626; }
#c360App .c3-fbtn.f-purple { border-left: 3px solid #7C3AED; } #c360App .c3-fbtn.f-teal { border-left: 3px solid #0D9488; }
#c360App .c3-fbtn.f-amber { border-left: 3px solid #EAB308; } #c360App .c3-fbtn.f-slate { border-left: 3px solid #64748B; }

/* mini tables */
#c360App .c3-table-wrap { overflow-x: auto; margin-top: 10px; }
#c360App .c3-mini-table { width: 100%; border-collapse: collapse; font-size: 13px; }
#c360App .c3-mini-table th { text-align: left; padding: 8px 10px; background: #F4F8F5; font-size: 12px; color: var(--ink2); border-bottom: 1px solid var(--line); white-space: nowrap; }
#c360App .c3-mini-table td { padding: 8px 10px; border-bottom: 1px solid var(--line2); }
#c360App .c3-spark { width: 100%; height: 64px; margin-top: 10px; background: #F8FAF8; border-radius: var(--r-sm); }
#c360App .c3-spark polyline { fill: none; stroke: var(--g600); stroke-width: 2.5; vector-effect: non-scaling-stroke; stroke-linejoin: round; }

/* documents */
#c360App .c3-doc-search { margin-left: auto; min-width: 220px; }
#c360App .c3-docs { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 12px; }
#c360App .c3-doc { display: flex; flex-direction: column; background: #fff; border: 1px solid var(--line); border-radius: var(--r); overflow: hidden; box-shadow: var(--shadow); }
#c360App .c3-doc-prev { position: relative; display: grid; place-items: center; height: 160px; background: #EAF2EC; text-decoration: none; overflow: hidden; }
#c360App .c3-doc-prev img, #c360App .c3-doc-prev video { width: 100%; height: 100%; object-fit: cover; pointer-events: none; }
#c360App .c3-doc-ic { font-size: 46px; }
#c360App .c3-play { position: absolute; width: 50px; height: 50px; display: grid; place-items: center; border-radius: 50%; background: rgba(23,96,58,.9); color: #fff; font-size: 20px; border: 3px solid #fff; }
#c360App .c3-doc-b { display: grid; gap: 4px; padding: 10px 12px; flex: 1; justify-items: start; }
#c360App .c3-doc-b b { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; max-width: 100%; }
#c360App .c3-doc-b small { font-size: 12px; color: var(--mute); }
#c360App .c3-doc-act { display: grid; grid-template-columns: 1fr 1fr; border-top: 1px solid var(--line2); }
#c360App .c3-doc-act a { padding: 9px; text-align: center; font-size: 13px; font-weight: 700; text-decoration: none; color: var(--g700); }
#c360App .c3-doc-act a + a { border-left: 1px solid var(--line2); }
#c360App .c3-doc-act a:hover { background: var(--mint); }

/* stock / conversions */
#c360App .c3-split { display: grid; grid-template-columns: repeat(2, minmax(0,1fr)); gap: 14px; align-items: start; }
#c360App .c3-split > section { display: grid; gap: 10px; min-width: 0; }
#c360App .c3-split .c3-h4 { margin-top: 0; }
#c360App .c3-stock-item { display: grid; grid-template-columns: minmax(0,1fr) auto; gap: 2px 10px; padding: 8px 10px; background: #F8FAF8; border-radius: var(--r-sm); font-size: 13px; }
#c360App .c3-stock-item small { grid-column: 1 / -1; color: var(--mute); font-size: 12px; }
#c360App .c3-conv { display: grid; grid-template-columns: minmax(0,1fr) 44px minmax(0,1fr); gap: 10px; align-items: center; }
#c360App .c3-conv h5 { font-size: 13px; font-weight: 800; margin-bottom: 6px; }
#c360App .c3-conv-row { padding: 8px 10px; margin-bottom: 6px; border-radius: var(--r-sm); background: var(--warn-bg); border: 1px solid var(--warn-line); }
#c360App .c3-conv-row.is-to { background: var(--ok-bg); border-color: var(--ok-line); }
#c360App .c3-conv-row b { display: block; font-size: 13px; }
#c360App .c3-conv-row span { font-size: 12px; color: var(--ink2); }
#c360App .c3-conv-arrow { display: grid; place-items: center; width: 44px; height: 44px; border-radius: 12px; background: var(--mint); font-size: 20px; color: var(--g700); }

/* remarks */
#c360App .c3-note-row { display: grid; grid-template-columns: 170px minmax(0,1fr); gap: 8px; }
#c360App .c3-note-row textarea { resize: vertical; min-height: 84px; width: 100%; }
#c360App .c3-note-foot { display: flex; justify-content: space-between; align-items: center; }
#c360App .c3-remarks { display: grid; gap: 8px; }
#c360App .c3-remark { padding: 11px 13px; background: #fff; border: 1px solid var(--line); border-radius: var(--r-sm); }
#c360App .c3-remark-h { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; margin-bottom: 5px; }
#c360App .c3-remark-h b { font-size: 13px; } #c360App .c3-remark-h small { font-size: 12px; color: var(--mute); }
#c360App .c3-remark p { font-size: 14px; white-space: pre-wrap; }

/* messages */
#c360App .c3-split-msg { grid-template-columns: minmax(0,1.2fr) minmax(0,1fr); }
#c360App .c3-lbl { display: grid; gap: 4px; font-size: 12px; font-weight: 700; color: var(--mute); }
#c360App .c3-lbl .c3-input { width: 100%; font-weight: 500; color: var(--ink); }
#c360App .c3-tpls { display: flex; flex-wrap: wrap; gap: 6px; }
#c360App .c3-tpl { padding: 7px 11px; border: 1px solid var(--line); border-radius: var(--r-sm); background: #fff; font-size: 13px; font-weight: 600; cursor: pointer; color: var(--ink2); }
#c360App .c3-tpl.is-on { background: var(--g800); border-color: var(--g800); color: #fff; }
#c360App .c3-tpl.is-on .c3-pill { background: rgba(255,255,255,.2); color: #fff; border-color: transparent; }
#c360App .c3-msg-actions { display: flex; gap: 8px; flex-wrap: wrap; }
#c360App .c3-rules { display: grid; gap: 6px; }
#c360App .c3-rule { display: grid; grid-template-columns: 36px minmax(0,1fr) auto; gap: 10px; align-items: center; padding: 9px 10px; border: 1px solid var(--line2); border-radius: var(--r-sm); background: #FBFCFB; }
#c360App .c3-rule-ic { display: grid; place-items: center; width: 36px; height: 36px; border-radius: 10px; background: var(--mint); font-size: 17px; }
#c360App .c3-rule b { display: block; font-size: 13px; } #c360App .c3-rule small { font-size: 12px; color: var(--mute); }
#c360App .c3-switch { padding: 3px 10px; border-radius: 999px; font-size: 12px; font-weight: 700; background: var(--slate-bg); color: var(--slate); }

#c360App .c3-more-wrap { display: flex; justify-content: center; margin-top: 14px; }
#c360App .c3-pager-sm { display: flex; justify-content: center; align-items: center; gap: 10px; margin-top: 14px; font-size: 13px; color: var(--mute); }

/* toasts */
#c360App .c3-toasts { position: fixed; right: 18px; bottom: 18px; z-index: 1000; display: grid; gap: 8px; }
#c360App .c3-toast { padding: 11px 16px; border-radius: var(--r-sm); background: var(--g900); color: #fff; font-size: 14px; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,.2); animation: c3in .2s ease; }
#c360App .c3-toast.tone-warn { background: #8A4B05; } #c360App .c3-toast.tone-neg { background: #9B1C13; }
@keyframes c3in { from { opacity: 0; transform: translateY(8px); } }

/* ---------- responsive ---------- */
@media (max-width: 1400px) {
  #c360App .c3-c4 { grid-template-columns: repeat(3, minmax(0,1fr)); }
  #c360App .c3-hero-kpis { grid-template-columns: repeat(3, minmax(0,1fr)); }
  #c360App .c3-hk:nth-child(3) { border-right: 0; }
  #c360App .c3-hk:nth-child(-n+3) { border-bottom: 1px solid rgba(255,255,255,.1); }
}
@media (max-width: 1100px) {
  #c360App .c3-kpi-strip { grid-template-columns: repeat(3, minmax(0,1fr)); }
  #c360App .c3-secs, #c360App .c3-c2, #c360App .c3-split, #c360App .c3-split-msg, #c360App .c3-dlists { grid-template-columns: 1fr; }
  #c360App .c3-c4 { grid-template-columns: repeat(2, minmax(0,1fr)); }
  #c360App .c3-g4, #c360App .c3-g5 { grid-template-columns: repeat(2, minmax(0,1fr)); }
  #c360App .c3-hero-main { grid-template-columns: auto minmax(0,1fr); }
  #c360App .c3-hero-actions { grid-column: 1 / -1; justify-content: flex-start; }
  #c360App .c3-hero-actions .c3-close { position: absolute; top: 14px; right: 14px; }
}
@media (max-width: 720px) {
  #c360App { width: 100%; margin: 0; }
  #c360App .c3-mast, #c360App .c3-filters-panel { border-radius: 0; padding-left: 14px; padding-right: 14px; }
  #c360App .c3-filters-panel { position: static; }
  #c360App .c3-kpi-strip { grid-template-columns: repeat(2, minmax(0,1fr)); }
  #c360App .c3-sel, #c360App .c3-search { flex: 1 1 100%; }
  #c360App .c3-modal { width: 100vw; height: 100dvh; border-radius: 0; }
  #c360App .c3-avatar { width: 76px; height: 76px; }
  #c360App .c3-avatar-in span { font-size: 22px; }
  #c360App .c3-hero h2 { font-size: 21px; }
  #c360App .c3-hero-kpis, #c360App .c3-c4, #c360App .c3-g3, #c360App .c3-g2, #c360App .c3-g4, #c360App .c3-g5, #c360App .c3-note-row, #c360App .c3-conv { grid-template-columns: 1fr; }
  #c360App .c3-hk { border-right: 0; border-bottom: 1px solid rgba(255,255,255,.1); }
  #c360App .c3-mbody { padding: 12px; }
  #c360App .c3-alerts, #c360App .c3-timeline { grid-template-columns: 1fr; }
  #c360App .c3-drawer-sum { grid-template-columns: repeat(2, 1fr); }
}
@media (prefers-reduced-motion: reduce) {
  #c360App *, #c360App *::before, #c360App *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; }
}
@media print {
  #c360App .c3-filters-panel, #c360App .c3-dash, #c360App .c3-overlay { display: none !important; }
}
/* Client 360 · cream, forest and fine gold UI · presentation only */
body.c360-page{background:#f7f5ed!important}
#c360App{--g950:#102e23;--g900:#173e2e;--g800:#20513a;--g700:#286343;--g600:#347a50;--g500:#52956b;--mint:#edf5e9;--mint2:#dfecd9;--canvas:#f7f5ed;--paper:#fffefa;--ink:#203329;--ink2:#405348;--mute:#5e6b60;--line:#d9d7c5;--line2:#eae8dc;--gold:#aa8741;--gold-soft:#eee3c4;--r-lg:16px;--r:11px;--shadow:0 3px 14px rgba(31,55,39,.055);--shadow-lg:0 14px 48px rgba(19,45,31,.18);font-size:13px;line-height:1.5;margin-top:12px}
#c360App :is(button,a,input,select,textarea):focus-visible{outline:2px solid #aa8741;outline-offset:3px}
#c360App .c3-mast{padding:16px 22px;background:radial-gradient(ellipse at 100% 0,rgba(166,137,66,.15),transparent 58%),linear-gradient(110deg,#102e23,#20513a);border:1px solid #a68c50;border-bottom:0;box-shadow:0 8px 28px rgba(20,49,32,.1)}
#c360App .c3-brand{background:#f3ecd8;color:#173e2e;border:1px solid #cfba80;letter-spacing:1.4px}
#c360App .c3-mast h1{font-size:clamp(22px,2vw,29px);letter-spacing:-.7px;font-weight:800;line-height:1.2;color:#fffdf5}
#c360App .c3-mast p{color:#e2eadb;font-size:12px;max-width:720px;margin-top:5px}
#c360App .c3-count-pill{border-color:#a68c50;background:rgba(248,244,226,.09);color:#fff9e8;font-size:12px}
#c360App .c3-mast .c3-btn-light{background:#f6edd6;border-color:#d2bb7b;color:#173e2e}
#c360App .c3-filters-panel{padding:12px 20px;gap:8px;background:rgba(255,254,249,.98);border:1px solid #c8ba94;border-top:2px solid #b89951;box-shadow:0 5px 16px rgba(32,48,28,.045)}
#c360App .c3-btn{min-height:35px;border-radius:8px;padding:7px 12px;font-size:12px;border-color:#d6d8c9;background:#fffefa;color:#243d2e}
#c360App .c3-btn-primary{background:linear-gradient(110deg,#173e2e,#286343);color:#fffef5;border-color:#20513a;box-shadow:0 2px 5px rgba(19,61,37,.1)}
#c360App .c3-btn-primary:hover{background:#102e23}
#c360App .c3-btn-sm{min-height:30px;padding:5px 10px}
#c360App .c3-btn-danger{color:var(--neg);background:var(--neg-bg);border-color:var(--neg-line)}
#c360App .c3-btn-danger.is-on{background:var(--neg);color:white}
#c360App .c3-btn-wa{background:#168544;color:white;border-color:#168544}
#c360App :is(.c3-search,.c3-sel,.c3-date,.c3-input,.c3-select-l select){border-color:#d3d6c6;background:#fffefa;color:#24392b;font-size:13px;border-radius:8px}
