#c360App .c3-statusbar{font-size:12px;color:#53604f;border-top:1px solid #ece6d4;padding-top:6px}
#c360App .c3-kpi-strip{gap:10px;margin:12px 0}
#c360App .c3-kpi-card{position:relative;padding:13px 15px;background:linear-gradient(125deg,#fffefa 48%,#eef4e8);border:1px solid #d7cfb8;border-top:2px solid #b69b60;box-shadow:var(--shadow);min-width:0}
#c360App .c3-kpi-card:nth-child(2),#c360App .c3-kpi-card:nth-child(3){border-top-color:#3c7c50;background:linear-gradient(125deg,#fffefa 48%,#e5f0df)}
