#c360App .c3-kpi-v{font-size:clamp(20px,1.8vw,27px);line-height:1.3;margin:5px 0;white-space:normal;overflow:visible;text-overflow:clip;overflow-wrap:anywhere;letter-spacing:-.5px}
#c360App .c3-kpi-hint{font-size:11px;color:#56654f;line-height:1.45}
#c360App :is(.c3-table-card,.c3-dash,.c3-sec,.c3-card,.c3-doc,.c3-dlist){background:#fffefa;border-color:#d8d2bb;box-shadow:var(--shadow)}
#c360App .c3-table{min-width:1180px;table-layout:auto}
#c360App .c3-table th{background:#e8efdf;color:#264c34;font-size:11px;letter-spacing:.3px;padding:10px 11px;border-bottom:1px solid #baa77b}
