        ${r.overdue ? `<div class="c3-mini tone-neg">⏰ ${r.overdue} overdue</div>` : r.withDues > 1 ? `<div class="c3-mini tone-warn">🧾 ${r.withDues} with dues</div>` : ""}</td>
      <td><span class="c3-pill tone-${med ? "neg" : "ok"}">${med ? "🩺 Medical" : "🌿 Non-medical"}</span></td>
      <td>${r.branches.map(b => `<span class="c3-chip">${esc(b)}</span>`).join(" ") || "—"}</td>
      <td class="t-c c3-sticky"><button type="button" class="c3-inv-btn${r.pending > 0 ? " has-due" : ""}" data-drawer="${esc(r.id)}">🧾 <b>${r.invCount}</b></button></td>
    </tr>`;
  }).join("");

  const pager = $("#c3Pager");
  pager.hidden = pages <= 1;
  if (pages > 1) {
    $("#c3PageInfo").textContent = `${start + 1}–${Math.min(start + CFG.PAGE_SIZE, total)} of ${total}`;
    $("#c3Prev").disabled = S.page === 1;
    $("#c3Next").disabled = S.page === pages;
    $("#c3PageNums").innerHTML = pageRange(S.page, pages).map(n => n === "…" ? `<span class="c3-dots">…</span>`
      : `<button type="button" class="c3-pg${n === S.page ? " is-on" : ""}" data-page="${n}">${n}</button>`).join("");
  }
}
function pageRange(cur, total) {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1);
  const out = [1];
  const s = Math.max(2, cur - 2), e = Math.min(total - 1, cur + 2);
  if (s > 2) out.push("…");
  for (let i = s; i <= e; i++) out.push(i);
  if (e < total - 1) out.push("…");
  out.push(total);
  return out;
}

