   GLOBAL CLIENT LOOKUP  (fixed)
   -------------------------------------------------------------------------- */
let lookSeq = 0, lookTimer = null, lookRows = [];

function lookupRule(v) {
  const t = String(v || "").trim();
  const d = t.replace(/\D/g, "");
  const nonDigit = t.replace(/[\s+\-()]/g, "");
  if (d && d.length === nonDigit.length) return { ok: d.length >= 3, type: "mobile", q: d };
  return { ok: t.length >= 3, type: "name", q: t };
}

function hideLookup() {
  const el = $("#c3Lookup");
  if (el) el.hidden = true;
  const s = $("#c3Search");
  if (s) s.setAttribute("aria-expanded", "false");
}

const LOOK_FIELDS_FULL = ["name", "patient_name", "mobile", "sex", "branch_name"];
const LOOK_FIELDS_MIN  = ["name", "patient_name", "mobile", "sex"];

async function lookPatients(filters) {
  let rows = await safe(list("Patient", filters, LOOK_FIELDS_FULL, 30, "modified desc"), null);
  if (rows === null) rows = await safe(list("Patient", filters, LOOK_FIELDS_MIN, 30, "modified desc"), []);
  return rows || [];
}


/* --------------------------------------------------------------------------
   BRANCH-SAFE CLIENT LOOKUP API
   Server resolves the logged-in user's branch and returns only Patients that
   belong to that branch. This avoids the frappe.client.get_list inconsistency
   seen for branch logins.
   -------------------------------------------------------------------------- */
async function c3BranchSafeGet(params) {
  try {
    const qs = new URLSearchParams();

    Object.keys(params || {}).forEach(key => {
      const value = params[key];
      if (value !== undefined && value !== null) {
        qs.set(key, String(value));
      }
    });

    /*
     * IMPORTANT:
     * Use GET for this read-only API.
     * This avoids website/iframe CSRF-token differences that can make a
     * branch login silently fall back to the old permission-filtered search.
     */
    const res = await fetch(
      "/api/method/life_client360_branch_patient_lookup?" +
        qs.toString(),
      {
        method: "GET",
        credentials: "same-origin",
        headers: {
          "Accept": "application/json"
        },
        cache: "no-store"
      }
    );

    let data = {};
    try {
      data = await res.json();
    } catch (e) {
      data = {};
    }

    if (!res.ok) {
      console.warn(
        "[CLIENT-360 v8.27] branch-safe API HTTP error",
        res.status,
        data
      );
      return null;
    }

    const result =
      data && data.message !== undefined
        ? data.message
        : data;

    console.info(
      "[CLIENT-360 v8.27] branch-safe API result",
      result
    );

    return result || null;
  } catch (err) {
    console.warn(
      "[CLIENT-360 v8.27] branch-safe API failed",
      err
    );
    return null;
  }
}

async function c3BranchSafePatientSearch(q) {
  const r = await c3BranchSafeGet({
    action: "search",
    q: String(q || "").trim()
  });

  if (!r || !r.ok || !Array.isArray(r.rows)) {
    return null;
  }

  return r;
}

async function c3BranchSafePatientRow(patient) {
  const r = await c3BranchSafeGet({
    action: "row",
    patient: String(patient || "").trim()
  });

  if (!r || !r.ok || !r.patient) {
    return null;
  }

  return r;
}


function c3PatientLookupShape(p) {
  if (!p) return null;

  return {
    name: p.name || p.value || "",
    patient_name:
      p.patient_name ||
      p.first_name ||
      p.label ||
      p.name ||
      p.value ||
      "",
    mobile: p.mobile || "",
    sex: p.sex || "",
    branch_name:
      p.branch_name ||
      p.custom_branch ||
      p.branch ||
      "",
    custom_branch:
      p.custom_branch ||
      p.branch_name ||
      p.branch ||
      ""
  };
}

/*
 * Exact mobile lookup must NOT depend on Therapy Plan/date filters.
 *
 * The normal fuzzy lookup uses frappe.client.get_list. On some branch-user
 * sessions that query can return no rows even though the Patient exists.
 * For a full mobile number, use multiple independent Frappe lookup paths:
 *
 *   1. frappe.client.get_value with exact mobile
 *   2. Patient get_list with exact mobile
 *   3. Frappe's standard Link search
 *
 * As soon as one path finds the Patient, load the actual Patient document
 * so branch_name/custom_branch are accurate.
 */
async function c3FindPatientExactMobile(raw) {
  const q = cleanMobile(raw);
  if (q.length < 8) return [];

  async function makePatient(name, fallback) {
    name = String(name || "").trim();
    if (!name) return null;

    const doc = await safe(getDoc("Patient", name), null);

    if (doc) {
      const shaped = c3PatientLookupShape(doc);

      if (shaped) {
        const pm = cleanMobile(shaped.mobile);

        if (
          !pm ||
          pm === q ||
          pm.includes(q) ||
          q.includes(pm)
        ) {
          if (!shaped.mobile) shaped.mobile = q;
          shaped._exact_mobile_match = true;
          return shaped;
        }
      }
    }

    /*
     * Do not discard a valid standard-link-search result only because
     * frappe.client.get cannot read the complete Patient document.
     */
    const shaped = c3PatientLookupShape(
      Object.assign({}, fallback || {}, {
        name,
        mobile: (fallback && fallback.mobile) || q
      })
    );

    if (shaped) {
      shaped.mobile = q;
      shaped._exact_mobile_match = true;
      return shaped;
    }

    return null;
  }

  /*
   * PATH 1 — standard Patient Link search.
   * Patient.mobile is configured as a Patient search field.
   * This is the same lookup mechanism Frappe Link controls use.
   */
  const linkResponse = await safe(
    call("frappe.desk.search.search_link", {
      doctype: "Patient",
      txt: q,
      page_length: 50,
      filters: {}
    }),
    []
  );

  const linkRows = Array.isArray(linkResponse)
    ? linkResponse
    : (
        linkResponse &&
        Array.isArray(linkResponse.results)
          ? linkResponse.results
          : []
      );

  for (const item of linkRows) {
    const name = String(
      (item && (item.value || item.name)) || ""
    ).trim();

    if (!name) continue;

    const searchText = [
      item.value,
      item.name,
      item.label,
      item.description
    ].filter(Boolean).join(" ");

    const searchDigits = cleanMobile(searchText);

    /*
     * With a full number, a single Patient link-search result is enough
     * to attempt opening that Patient. Where description includes mobile,
     * verify the digits too.
     */
    if (
      linkRows.length === 1 ||
      searchDigits.includes(q) ||
      q.includes(searchDigits)
    ) {
      const patient = await makePatient(name, {
        name,
        patient_name:
          item.label ||
          item.value ||
          name,
        mobile: q
      });

      if (patient) return [patient];
    }
  }

  /*
   * PATH 2 — exact get_value.
   */
  const candidates = [];
  const add = value => {
    value = String(value || "").trim();
    if (value && !candidates.includes(value)) {
      candidates.push(value);
    }
  };

  add(q);
  add("0" + q);
  add("91" + q);
  add("+91" + q);

  for (const mobile of candidates) {
    const row = await safe(
      call("frappe.client.get_value", {
        doctype: "Patient",
        filters: { mobile },
        fieldname: [
          "name",
          "patient_name",
          "first_name",
          "mobile",
          "sex",
          "branch_name",
          "custom_branch"
        ]
      }),
      null
    );

    if (row && row.name) {
      const patient = await makePatient(
        row.name,
        row
      );

      if (patient) return [patient];
    }
  }

  /*
   * PATH 3 — exact Patient list.
   */
  for (const mobile of candidates) {
    const rows = await safe(
      list(
        "Patient",
        [["mobile", "=", mobile]],
        [
          "name",
          "patient_name",
          "first_name",
          "mobile",
          "sex",
          "branch_name",
          "custom_branch"
        ],
        50,
        "modified desc"
      ),
      []
    );

    for (const row of rows || []) {
      if (!row || !row.name) continue;

      const pm = cleanMobile(row.mobile);

      if (
        pm === q ||
        pm.includes(q) ||
        q.includes(pm)
      ) {
        const patient = await makePatient(
          row.name,
          row
        );

        if (patient) return [patient];
      }
    }
  }

  /*
   * PATH 4 — partial digit fallback.
   */
  const probes = [
    q.slice(0, 5),
    q.slice(-5),
    q.slice(0, 4),
    q.slice(-4),
    q.slice(0, 3),
    q.slice(-3)
  ].filter((v, i, arr) =>
    v && arr.indexOf(v) === i
  );

  for (const probe of probes) {
    const rows = await lookPatients([
      ["mobile", "like", "%" + probe + "%"]
    ]);

    for (const row of rows || []) {
      const pm = cleanMobile(row.mobile);

      if (
        pm === q ||
        pm.includes(q) ||
        q.includes(pm)
      ) {
        const patient = await makePatient(
          row.name,
          row
        );

        if (patient) return [patient];
      }
    }
  }

  return [];
}

async function runLookup(v) {
  const rule = lookupRule(v);
  if (!rule.ok) { hideLookup(); return; }

  const seq = ++lookSeq;
  const el = $("#c3Lookup");
  if (!el) return;
  el.hidden = false;
  el.innerHTML = `<div class="c3-look-state"><span class="c3-spin"></span> Searching all clients…</div>`;

  const found = [];

  /*
   * FIRST: use the branch-safe server API.
   * This is authoritative for branch users and is independent of the current
   * Therapy Plan date filter.
   */
  const branchSafe = await c3BranchSafePatientSearch(rule.q);

  if (seq !== lookSeq) return;

  if (branchSafe && branchSafe.rows.length) {
    branchSafe.rows.forEach(row => {
      if (
        rule.type === "mobile" &&
        cleanMobile(rule.q).length >= 8 &&
        cleanMobile(row.mobile) === cleanMobile(rule.q)
      ) {
        row._exact_mobile_match = true;
      }
      found.push(row);
    });
  }

  if (!found.length && rule.type === "mobile") {
    const q = cleanMobile(rule.q);

    /*
     * Full mobile number: first do an exact Patient lookup that is completely
     * independent of the current date/branch table data.
     */
    if (q.length >= 8) {
      const exactRows = await c3FindPatientExactMobile(q);
      if (exactRows && exactRows.length) {
        found.push(...exactRows);
      }
    }

    /*
     * Partial/fallback lookup for 3+ digits.
     * Keep this for suggestions while typing.
     */
    const probes = [];

    const pushProbe = v => {
      v = String(v || "").trim();
      if (v && !probes.includes(v)) probes.push(v);
    };

    pushProbe(q);

    if (q.length >= 10) {
      pushProbe("91" + q);
      pushProbe("0" + q);
    }

    if (q.length >= 5) {
      pushProbe(q.slice(0, 5));
      pushProbe(q.slice(-5));
    }

    if (q.length >= 4) {
      pushProbe(q.slice(0, 4));
      pushProbe(q.slice(-4));
    }

    if (q.length === 3) {
      pushProbe(q);
    }

    if (!found.length || q.length < 8) {
      for (const shape of probes) {
        const rows = await lookPatients([
          ["mobile", "like", "%" + shape + "%"]
        ]);

        if (rows && rows.length) {
          found.push(...rows);
        }

        if (found.length >= 60) break;
      }
    }

    /*
     * Last fallback:
     * Search Patient ID/name only if mobile search returned nothing.
     */
    if (!found.length) {
      found.push(
        ...await lookPatients([
          ["patient_name", "like", "%" + q + "%"]
        ])
      );
    }
  } else if (!found.length) {
    found.push(
      ...await lookPatients([
        ["patient_name", "like", "%" + rule.q + "%"]
      ])
    );
    found.push(
      ...await lookPatients([
        ["name", "like", "%" + rule.q + "%"]
      ])
    );
  }
  if (seq !== lookSeq) return;

  const seen = new Set();
  lookRows = found.filter(p => {
    if (!p || !p.name || seen.has(p.name)) return false;
    if (isExcluded(p.branch_name)) return false;

    if (rule.type === "mobile") {
      const pm = cleanMobile(p.mobile);
      const qm = cleanMobile(rule.q);

      /*
       * Exact/full mobile search:
       * accept normalized equality or containment after removing +91/0/etc.
       *
       * Partial 3+ digit search:
       * normal normalized containment.
       */
      const mobileMatches =
        pm === qm ||
        pm.includes(qm) ||
        qm.includes(pm) ||
        p._exact_mobile_match === true;

      if (!mobileMatches) return false;
    }

    seen.add(p.name);
    return true;
  }).slice(0, 15);

  $("#c3Search").setAttribute("aria-expanded", "true");

  if (!lookRows.length) {
    const serverBranches =
      branchSafe &&
      Array.isArray(branchSafe.branches)
        ? branchSafe.branches.join(", ")
        : "";

    const exactText =
      rule.type === "mobile" &&
      rule.q.length >= 8
        ? (
            branchSafe
              ? `Server checked branch: ${serverBranches || "not mapped"} — no matching client returned.`
              : "Branch-safe server lookup did not respond; fallback search also returned no client."
          )
        : "Try another spelling, or the first 3 digits of the mobile number.";

    el.innerHTML =
      `<div class="c3-look-state">` +
        `No client found for “${esc(rule.q)}”.<br>` +
        `<small>${esc(exactText)}</small>` +
      `</div>`;

    console.warn(
      "[CLIENT-360 v8.27] lookup returned zero rows",
      {
        query: rule.q,
        type: rule.type,
        branchSafe: branchSafe || null,
        user:
          (
            window.frappe &&
            frappe.session &&
            frappe.session.user
          ) || "unknown"
      }
    );

    return;
  }

  el.innerHTML = `<div class="c3-look-h">${lookRows.length} matching client${lookRows.length === 1 ? "" : "s"}</div>` +
    lookRows.map((p, i) => {
      const g = genderEmoji(p.sex);
      return `<div class="c3-look-item">
        <span class="c3-g">${g.e}</span>
        <div class="c3-look-main">
          <b>${esc(p.patient_name || p.name)}</b>
          <div class="c3-look-meta">${phoneHtml(p.mobile)}${(p.branch_name || p.custom_branch) ? `<span class="c3-chip">🏢 ${esc(p.branch_name || p.custom_branch)}</span>` : ""}</div>
        </div>
        <div class="c3-look-act">
          <button type="button" class="c3-btn c3-btn-primary c3-btn-sm" data-look-open="${i}">Open 360</button>
          <button type="button" class="c3-btn c3-btn-sm" data-look-row="${i}">Show in list</button>
        </div>
      </div>`;
    }).join("");

  if (lookRows.length === 1) {
    const p = lookRows[0];
    const typed = String(rule.q || "").trim();
    const typedMobile = cleanMobile(typed);
    const mobile = cleanMobile(p.mobile);

    const exactMobile =
      rule.type === "mobile" &&
      typedMobile.length >= 8 &&
      (
        mobile === typedMobile ||
        mobile.endsWith(typedMobile) ||
        typedMobile.endsWith(mobile) ||
        p._exact_mobile_match === true
      );

    const exactName =
      rule.type === "name" &&
      (
        lc(p.patient_name) === lc(typed) ||
        lc(p.name) === lc(typed)
      );

    if (exactMobile || exactName) {
      showSingleInList(p, {
        keepLookup: true,
        background: true
      }).catch(err => {
        console.warn("[CLIENT-360] exact global-search row load failed", err);
      });
    }
  }
}

const c3GlobalRowCache = new Map();
const c3GlobalRowLoading = new Map();

async function c3BuildGlobalClientRow(p) {
  if (!p || !p.name) return null;

  const pid = p.name;

  if (c3GlobalRowCache.has(pid)) {
    return c3GlobalRowCache.get(pid);
  }

  if (c3GlobalRowLoading.has(pid)) {
    return c3GlobalRowLoading.get(pid);
  }

  const promise = (async () => {
    /*
     * Prefer the branch-safe server API so branch users receive the complete
     * selected client's history even when normal get_list permissions omit it.
     */
    const safeRow = await c3BranchSafePatientRow(pid);

    let plans = [];
    let invs = [];
    let ses = [];
    let patientDoc = null;

    if (safeRow) {
      plans = safeRow.plans || [];
      invs = safeRow.invoices || [];
      ses = safeRow.sessions || [];
      patientDoc = safeRow.patient || null;
    } else {
      const local = await Promise.all([
        safe(
          list(
            "Therapy Plan",
            [["patient", "=", pid]],
            ["name", "patient_name", "start_date", "due_date", "branch", "custom_health_status", "status", "total_sessions", "total_sessions_completed"],
            500,
            "start_date asc"
          ),
          []
        ),
        safe(
          list(
            "Sales Invoice",
            [["patient", "=", pid], ["docstatus", "=", 1]],
            ["name", "posting_date", "due_date", "base_grand_total", "outstanding_amount", "status", "is_return", "branch"],
            2000,
            "posting_date desc"
          ),
          []
        ),
        safe(
          list(
            "Therapy Session",
            [["patient", "=", pid], ["docstatus", "!=", 2]],
            ["start_date", "creation", "branch"],
            5000,
            "start_date desc"
          ),
          []
        ),
        safe(getDoc("Patient", pid), null)
      ]);

      plans = local[0] || [];
      invs = local[1] || [];
      ses = local[2] || [];
      patientDoc = local[3] || null;
    }

    const ps = (plans || []).filter(x => !isExcluded(x.branch));
    const iv = (invs || []).filter(x => !isExcluded(x.branch));
    const ss = (ses || []).filter(x => !isExcluded(x.branch));
    const pt = patientDoc || p || {};

    const last = ss
      .map(s => d10(s.start_date || s.creation))
      .filter(Boolean)
      .sort()
      .pop() || null;

    const due = dueInfo(iv);
    S.invCache[pid] = iv;

    const states = ps.map(x =>
      planHealth({
        start: x.start_date,
        due: x.due_date,
        total: x.total_sessions,
        done: x.total_sessions_completed,
        status: x.status
      }).state
    );

    const patientBranchHistory = Array.isArray(pt.custom_brnch_list)
      ? pt.custom_brnch_list.map(x => x && x.branch)
      : [];

    const branches = [
      ...new Set([
        ...ps.map(x => x.branch),
        pt.branch_name,
        pt.custom_branch,
        pt.branch,
        p.branch_name,
        p.custom_branch,
        ...(Array.isArray(pt.branches) ? pt.branches : []),
        ...(Array.isArray(p.branches) ? p.branches : []),
        ...patientBranchHistory
      ].map(x => String(x || "").trim())
       .filter(b => b && !isExcluded(b)))
    ];

    const row = {
      id: pid,
      name: pt.patient_name || p.patient_name || pid,
      customer: pt.customer || "",
      mobile: cleanMobile(pt.mobile || p.mobile),
      sex: pt.sex || p.sex || "",
      joined:
        ps.map(x => x.start_date).filter(Boolean).sort()[0] ||
        d10(pt.custom_joining_date || pt.creation) ||
        "",
      last,
      visits: ss.length,
      paid: r0(iv.reduce((s, i) => s + num(i.base_grand_total) - num(i.outstanding_amount), 0)),
      pending: r0(due.pending),
      withDues: due.withDues,
      overdue: due.overdue,
      invCount: iv.filter(i => !Number(i.is_return)).length,
      medical: ps.some(x => lc(x.custom_health_status) === "medical") ? "Medical" : "Non-Medical",
      branches,
      status: clientStatus(last, ps),
      growth:
        states.includes("overdue") ? { c: "neg", l: "⛔ Overdue plan" } :
        states.includes("behind") ? { c: "warn", l: "▼ Behind" } :
        states.includes("ok") ? { c: "ok", l: "▲ On track" } :
        states.includes("done") ? { c: "info", l: "🏁 Done" } :
        { c: "mute", l: "—" },
      _globalSearch: true
    };

    c3GlobalRowCache.set(pid, row);
    return row;
  })().finally(() => {
    c3GlobalRowLoading.delete(pid);
  });

  c3GlobalRowLoading.set(pid, promise);
  return promise;
}

function c3UpsertGlobalSearchRow(row) {
  if (!row || !row.id) return;

  const ix = S.all.findIndex(x => x.id === row.id);

  if (ix >= 0) {
    const existing = S.all[ix];
    const branches = [
      ...new Set([
        ...(existing.branches || []),
        ...(row.branches || [])
      ])
    ];

    S.all[ix] = Object.assign({}, existing, row, { branches });
  } else {
    S.all.unshift(row);
  }
}

async function showSingleInList(p, options) {
  const opts = options || {};

  if (!opts.keepLookup) hideLookup();

  setStatus(`⏳ Loading full history for <b>${esc(p.patient_name || p.name)}</b>…`);

  if (!opts.background) {
    renderLoading();
  }

  const row = await c3BuildGlobalClientRow(p);
  if (!row) return;

  c3UpsertGlobalSearchRow(row);

  // Date range is bypassed only for this searched client.
  // Branch / Status / Payment Mode / Pending still apply normally.
  applyFilters();

  if (!opts.keepLookup) {
    setStatus(
      `Full history for <b>${esc(row.name)}</b> — search can show this client outside the selected plan-start date range.`
    );
  }
}

/* ---------------- network dashboard ---------------- */
async function loadDash() {
  const set = (id, v) => { const el = $("#" + id); if (el) el.innerHTML = v; };
  $("#c3DashUpdated").textContent = "Updating…";
  try {
    const t = TODAY();
    const d90 = addDays(t, -CFG.IRREGULAR_DAYS), d30 = addDays(t, -CFG.ACTIVE_DAYS);
    const now = new Date();
    const fyFrom = (now.getMonth() >= 3 ? now.getFullYear() : now.getFullYear() - 1) + "-04-01";
    const dFrom = S.from || billingMonth(0)[0];
    let dTo = S.to || t; if (dTo > t) dTo = t;
    const fetchFrom = [fyFrom, dFrom, d90].sort()[0];

    const [plansRaw, sesRaw] = await Promise.all([
      list("Therapy Plan", [], ["patient", "status", "branch"], 60000),
      list("Therapy Session", [["start_date", ">=", fetchFrom], ["start_date", "<=", t], ["docstatus", "!=", 2]], ["patient", "start_date", "branch"], 80000)
    ]);
    const plans = plansRaw.filter(p => p.patient && !isExcluded(p.branch));
    const ses = sesRaw.filter(s => !isExcluded(s.branch));
    const patients = [...new Set(plans.map(p => p.patient))];

    const last = {};
    ses.forEach(s => { const d = d10(s.start_date); if (d >= d90 && (!last[s.patient] || d > last[s.patient])) last[s.patient] = d; });
    let active = 0, irregular = 0, inactive = 0;
    patients.forEach(p => { const l = last[p]; if (!l) inactive++; else if (l >= d30) active++; else irregular++; });

    const completed = new Set(plans.filter(p => lc(p.status) === "completed").map(p => p.patient)).size;
    const bm = {};
    plans.forEach(p => { if (p.branch) (bm[p.branch] = bm[p.branch] || new Set()).add(p.patient); });
    const bNames = Object.keys(bm);
    const top = bNames.sort((a, b) => bm[b].size - bm[a].size)[0] || "—";
    const inServ = {};
    plans.filter(p => !["completed", "cancelled"].includes(lc(p.status))).forEach(p => { if (p.branch) inServ[p.branch] = (inServ[p.branch] || 0) + 1; });

    const days = Math.max(1, daysBetween(dFrom, dTo) + 1);
    const months = Math.max(1, (daysBetween(fyFrom, t) + 1) / 30.44);
    const dB = {}, fB = {};
    let dT = 0, fT = 0;
    ses.forEach(s => {
      const d = d10(s.start_date), b = s.branch || "Unknown";
      if (d >= fyFrom) { fB[b] = (fB[b] || 0) + 1; fT++; }
      if (d >= dFrom && d <= dTo) { dB[b] = (dB[b] || 0) + 1; dT++; }
    });
    const bars = (obj, fmt) => {
      const e = Object.entries(obj).sort((a, b) => b[1] - a[1]);
      const max = e.length ? e[0][1] : 1;
      return e.length ? e.map(([b, n]) => `<div class="c3-bar"><span class="c3-bar-l">${esc(b)}</span><span class="c3-bar-t"><i style="width:${Math.max(4, n / max * 100)}%"></i></span><b>${fmt(n)}</b></div>`).join("") : `<div class="c3-empty-sm">No data in this period.</div>`;
    };

    set("d-total", patients.length.toLocaleString("en-IN"));
    set("d-active", active.toLocaleString("en-IN"));
    set("d-irregular", irregular.toLocaleString("en-IN"));
    set("d-inactive", inactive.toLocaleString("en-IN"));
    set("d-completed", completed.toLocaleString("en-IN"));
    set("d-avg", bNames.length ? Math.round(patients.length / bNames.length).toLocaleString("en-IN") : "0");
    set("d-top", esc(top));
    set("d-daily", (dT / days).toFixed(1));
    set("d-daily-sub", `${fdate(dFrom)} → ${fdate(dTo)} (${days}d)`);
    set("d-monthly", Math.round(fT / months).toLocaleString("en-IN"));
    set("d-inserv", bars(inServ, n => n));
    set("d-dailyb", bars(dB, n => (n / days).toFixed(1) + "/d"));
    set("d-monthlyb", bars(fB, n => Math.round(n / months) + "/mo"));
    $("#c3DashUpdated").textContent = "Updated " + new Date().toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" });
  } catch (e) {
    console.error("[CLIENT-360] dash", e);
    $("#c3DashUpdated").textContent = "Dashboard failed — " + e.message;
  }
}

