const M = { pid: null, b: null, tab: "overview", cache: {}, seq: 0 };

function therapyRows(plan) {
  const out = [], seen = new Set();
  const nameF = ["therapy_type", "therapy", "service", "service_name", "item_code", "item", "package", "package_name"];
  const totF = ["no_of_sessions", "sessions", "total_sessions", "qty", "quantity", "booked_quantity"];
  const doneF = ["sessions_completed", "completed_sessions", "total_sessions_completed", "availed_quantity", "used_sessions", "consumed_sessions", "completed_quantity"];
  Object.keys(plan || {}).forEach(k => {
    const v = plan[k];
    if (!Array.isArray(v)) return;
    v.forEach(row => {
      if (!row || typeof row !== "object") return;
      const n = nameF.map(f => row[f]).find(Boolean);
      if (!n) return;
      const pick = fs => { for (const f of fs) if (row[f] != null && row[f] !== "") return num(row[f]); return 0; };
      const total = pick(totF), done = pick(doneF);
      const key = n + "|" + total + "|" + done;
      if (seen.has(key)) return;
      seen.add(key);
      out.push({ therapy: n, total, done, balance: Math.max(0, total - done) });
    });
  });
  return out;
}

function detectPhones(p) {
  const out = [], seen = new Set();
  const add = (v, label) => { const d = cleanMobile(v); if (d.length >= 10 && !seen.has(d)) { seen.add(d); out.push({ label, number: d }); } };
  add(p.mobile, "Primary");
  Object.keys(p || {}).forEach(k => {
    if (k === "mobile") return;
    if (!/(mobile|phone|contact|whatsapp|alternate|alt_|emergency)/i.test(k)) return;
    const v = p[k];
    if (typeof v !== "string" && typeof v !== "number") return;
    const label = k.replace(/^custom_/, "").replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase());
    add(v, label);
  });
  return out;
}

function detectClientId(p) {
  const pref_ = ["custom_client_id", "client_id", "custom_patient_id", "patient_id", "custom_uhid", "uhid", "custom_registration_number", "registration_number", "custom_mr_number", "mr_number", "uid"];
  for (const k of pref_) if (p[k]) return { id: String(p[k]), real: true };
  const k2 = Object.keys(p).find(k => /(client|patient)_?(id|code|no)$|uhid|mrn|reg(istration)?_?(no|number)/i.test(k) && p[k] && typeof p[k] === "string");
  if (k2) return { id: p[k2], real: true };
  if (p.name && lc(p.name) !== lc(p.patient_name)) return { id: p.name, real: true };
  return { id: p.name || "—", real: false };
}

function referralInfo(p) {
  const by = [];
  const fields = [];
  Object.keys(p || {}).forEach(k => {
    if (!/(referr|refered|referred|reference_by|ref_by)/i.test(k)) return;
    fields.push(k);
    const v = p[k];
    if (v && (typeof v === "string" || typeof v === "number")) by.push({ field: k, value: String(v) });
  });
  return { by, fields };
}


/* --------------------------------------------------------------------------
   REFERRAL HERO SUMMARY
   - Incoming referral: who referred this client
   - Outgoing referral: clients referred by this client
   Reads both Patient referral fields and Therapy Plan reference-client fields.
   -------------------------------------------------------------------------- */
function c3ReferralGenericValue(v) {
  const s = lc(v);
  return !s || [
    "reference", "referral", "direct", "direct walk-in", "walk in", "walk-in",
    "existing customer", "call center", "website", "meta", "social media"
  ].includes(s);
}


/*
 * The live Billing backend does NOT store client referral in a dedicated
 * Therapy Plan field. It writes this exact audit note on Sales Invoice.remarks:
 *
 *   Referred by client: Client Name (Patient-ID)
 *
 * Read that source directly so CLIENT-360 always shows the same referral
 * selected during billing.
 */
function c3InvoiceReferralClient(inv) {
  const raw = stripHtml((inv && inv.remarks) || "").replace(/\s+/g, " ").trim();
  if (!raw) return null;

  let m = raw.match(/Referred by client:\s*([^|]+?)\s*\(([^()]+)\)(?=\s*(?:\||$))/i);

  if (m) {
    return {
      id: String(m[2] || "").trim(),
      name: String(m[1] || "").trim(),
      source: "Sales Invoice",
      kind: "client"
    };
  }

  /* Compatibility if an older invoice note contains the name but no ID. */
  m = raw.match(/Referred by client:\s*([^|]+)/i);
  if (m) {
    return {
      id: "",
      name: String(m[1] || "").replace(/\s*\([^()]+\)\s*$/, "").trim(),
      source: "Sales Invoice",
      kind: "client"
    };
  }

  return null;
}

function c3InvoiceWasReferredBy(inv, patientId, patientName) {
  const ref = c3InvoiceReferralClient(inv);
  if (!ref) return false;

  const rid = lc(ref.id);
  const rname = lc(ref.name);
  const pid = lc(patientId);
  const pname = lc(patientName);

  return !!(
    (pid && rid === pid) ||
    (pname && rname === pname)
  );
}


/*
 * IMPORTANT:
 * The Billing backend stores the selected "From an employee" referral
 * in Sales Invoice.remarks as:
 *
 *   Referred by employee: Employee Name
 *
 * Sales Invoice.custom_referring_name is NOT the referral employee on
 * this site; it is populated from the consultant/practitioner.
 */
function c3InvoiceReferralEmployee(inv) {
  const raw = stripHtml((inv && inv.remarks) || "")
    .replace(/\s+/g, " ")
    .trim();

  if (!raw) return null;

  const m = raw.match(
    /Referred by employee:\s*([^|]+?)(?=\s*(?:\||$))/i
  );

  if (!m) return null;

  const name = String(m[1] || "").trim();
  if (!name) return null;

  return {
    id: "",
    name,
    source: "Sales Invoice",
    kind: "employee"
  };
}

function c3UniqueReferralPush(arr, item) {
  if (!item) return;
  const id = String(item.id || "").trim();
  const name = String(item.name || item.value || "").trim();
  if (!id && !name) return;
  if (c3ReferralGenericValue(name)) return;

  const key = lc(id || name);
  if (!arr.some(x => lc(x.id || x.name) === key)) {
    arr.push({
      id,
      name: name || id,
      source: item.source || "",
      kind: item.kind || ""
    });
  }
}

function c3PlanIncomingReferrals(b) {
  const out = [];
  (b.plans || []).forEach(plan => {
    if (!plan || typeof plan !== "object") return;

    const idKeys = [];
    const nameKeys = [];

    Object.keys(plan).forEach(k => {
      const nk = lc(k);
      const isReferral = /(referr|refered|referred|reference|ref_by)/i.test(k);
      const isClient = /(client|patient)/i.test(k);
      if (!isReferral || !isClient) return;

      if (/name/i.test(k)) nameKeys.push(k);
      else idKeys.push(k);
    });

    [
      "reference_client", "custom_reference_client", "referral_client",
      "referred_by_client", "custom_referred_by_client", "ref_client"
    ].forEach(k => {
      if (Object.prototype.hasOwnProperty.call(plan, k) && !idKeys.includes(k)) idKeys.push(k);
    });

    [
      "reference_client_name", "custom_reference_client_name",
      "referral_client_name", "referred_by_client_name"
    ].forEach(k => {
      if (Object.prototype.hasOwnProperty.call(plan, k) && !nameKeys.includes(k)) nameKeys.push(k);
    });

    const refId = idKeys.map(k => plan[k]).find(Boolean) || "";
    const refName = nameKeys.map(k => plan[k]).find(Boolean) || "";

    if (refId || refName) {
      c3UniqueReferralPush(out, {
        id: String(refId || "").trim(),
        name: String(refName || refId || "").trim(),
        source: "Therapy Plan",
        kind: "client"
      });
    }
  });
  return out;
}

async function c3ResolveReferralNames(rows) {
  const out = [];
  for (const row of rows || []) {
    if (!row) continue;
    let id = String(row.id || "").trim();
    let name = String(row.name || "").trim();

    if (id && (!name || name === id)) {
      const p = await safe(getDoc("Patient", id), null);
      if (p) name = p.patient_name || p.name || name || id;
    }

    c3UniqueReferralPush(out, { id, name: name || id, source: row.source, kind: row.kind || "" });
  }
  return out;
}

function c3HeroReferralHtml(b) {
  const refs = b && b.lazy && b.lazy.referrals;
  if (!refs) return "";

  const html = [];

  (refs.by || []).slice(0, 2).forEach(r => {
    const who =
      r.kind === "employee" ? "employee" :
      r.kind === "client" ? "client" : "";
    const label = `🤝 Referred by${who ? " " + who : ""}: ${esc(r.name || r.id || "—")}`;

    if (r.kind === "client" && r.id && r.id !== b.pid) {
      html.push(`<button type="button" class="c3-chip c3-chip-btn c3-ref-hero-chip" data-c3-ref-open="${esc(r.id)}" title="Open referring client">${label}</button>`);
    } else {
      html.push(`<span class="c3-chip c3-ref-hero-chip">${label}</span>`);
    }
  });

  const brought = refs.brought || [];
  brought.slice(0, 3).forEach(r => {
    const nm = r.patient_name || r.name || "Client";
    html.push(
      `<button type="button" class="c3-chip c3-chip-btn c3-ref-hero-chip tone-ok" ` +
      `data-c3-ref-open="${esc(r.name)}" ` +
      `title="Open client referred by this client">` +
      `🎁 Referred client: ${esc(nm)}` +
      `</button>`
    );
  });

  if (brought.length > 3) {
    html.push(
      `<span class="c3-chip c3-ref-hero-chip tone-ok">` +
      `+${brought.length - 3} more referred` +
      `</span>`
    );
  }

  return html.join("");
}

function c3OpenDirectNewBill(pid) {
  if (!pid) return;

  /*
   * CLIENT-360 ONLY solution.
   * We do NOT require any Billing-page code change.
   *
   * 1) Open the existing Billing page in a new tab immediately from the
   *    user's click, so the browser does not block the popup.
   * 2) Because both pages are on portal.lifescc.com, CLIENT-360 can wait
   *    for the existing Billing JavaScript to finish booting.
   * 3) Call the Billing page's already-existing startBilling(pid), which
   *    opens that exact Patient directly in the Therapy Plan / New Bill workspace.
   */
  const billingUrl = portalLink("billing", pid);
  const winName = "life_new_bill_" + String(pid).replace(/[^a-z0-9_-]+/gi, "_");
  const billWin = window.open(billingUrl, winName);

  if (!billWin) {
    toast("Popup blocked. Allow popups for portal.lifescc.com and try New bill again.", "neg");
    return;
  }

  let attempts = 0;
  const maxAttempts = 240; // about 60 seconds
  let opened = false;

  const timer = window.setInterval(() => {
    attempts += 1;

    if (!billWin || billWin.closed) {
      window.clearInterval(timer);
      return;
    }

    try {
      const hasStartBilling = typeof billWin.startBilling === "function";
      const hasShowView = typeof billWin.showView === "function";
      const hasPatientApi = typeof billWin.getDoc === "function";

      /* Billing declares these as global var values and fills them during boot(). */
      const refsReady =
        Array.isArray(billWin.BRANCHES) &&
        Array.isArray(billWin.CATALOG) &&
        billWin.BRANCHES.length > 0 &&
        billWin.CATALOG.length > 0;

      const bootFailed = !!billWin.BOOT_ERR;

      if (hasStartBilling && hasShowView && hasPatientApi && (refsReady || bootFailed)) {
        window.clearInterval(timer);

        if (bootFailed && !refsReady) {
          try { billWin.focus(); } catch (_) {}
          toast("Billing opened, but its reference data did not finish loading.", "warn");
          return;
        }

        billWin.showView("billing");

        if (typeof billWin.showKpiRow === "function") {
          billWin.showKpiRow(false);
        }

        billWin.startBilling(pid);
        opened = true;

        try { billWin.focus(); } catch (_) {}
        return;
      }
    } catch (err) {
      /*
       * During the first navigation frames the new window can briefly be
       * unavailable. Keep waiting; both final pages are same-origin.
       */
    }

    if (attempts >= maxAttempts) {
      window.clearInterval(timer);
      try { billWin.focus(); } catch (_) {}
      if (!opened) {
        toast("Billing opened, but direct Therapy Plan loading timed out. Please try New bill once more.", "warn");
      }
    }
  }, 250);
}


