function medicalInfo(p, plans) {
  const issues = [];
  const keys = ["allergies", "medication", "medical_history", "surgical_history", "tobacco_past_use", "tobacco_current_use", "alcohol_past_use", "alcohol_current_use", "other_risk_factors", "blood_group"];
  Object.keys(p || {}).forEach(k => {
    const isMed = keys.includes(k) || /^custom_.*(medic|health|disease|condition|allerg|history|chronic|pregnan)/i.test(k);
    if (!isMed) return;
    const v = typeof p[k] === "string" ? stripHtml(p[k]) : "";
    if (!v || /^(no|none|nil|na|n\/a|-|0)$/i.test(v)) return;
    issues.push({ label: k.replace(/^custom_/, "").replace(/_/g, " ").replace(/\b\w/g, c => c.toUpperCase()), text: v, key: k });
  });
  const flagged = issues.filter(i => i.key !== "blood_group" && CFG.MEDICAL_KEYWORDS.some(w => (" " + lc(i.text)).includes(w)));
  const planMedical = plans.some(x => lc(x.custom_health_status) === "medical");
  return { issues, flagged, isMedical: planMedical || flagged.length > 0 || lc(p.custom_health_status) === "medical" };
}

async function loadBundle(pid) {
  const [patient, plansBasic, sessions, invoices, appts, followups] = await Promise.all([
    safe(getDoc("Patient", pid), { name: pid }),
    safe(list("Therapy Plan", [["patient", "=", pid]], ["name", "patient_name", "start_date", "due_date", "status", "branch", "custom_health_status", "total_sessions", "total_sessions_completed", "owner", "creation", "consultant_name", "custom_employee_name", "category"], 500, "start_date desc"), []),
    safe(list("Therapy Session", [["patient", "=", pid], ["docstatus", "!=", 2]], ["name", "start_date", "start_time", "therapy_type", "therapy_plan", "docstatus", "practitioner", "custom_practitioner_name", "duration", "branch", "before_weight", "after_weight", "weight_loss", "creation"], 5000, "start_date desc"), []),
    safe(list("Sales Invoice", [["patient", "=", pid], ["docstatus", "=", 1]], ["name", "patient", "patient_name", "posting_date", "due_date", "base_grand_total", "outstanding_amount", "status", "is_return", "branch", "owner", "remarks", "custom_therapy_plan", "custom_referring_name", "ref_practitioner"], 2000, "posting_date desc"), []),
    safe(list("Patient Appointment", [["patient", "=", pid]], ["name", "appointment_date", "appointment_time", "appointment_type", "call_back_status", "status", "practitioner", "practitioner_name", "department", "branch", "concern", "service_room", "service_unit", "therapy_type1", "therapy_type", "therapy_plan_1", "therapy_plan"], 2000, "appointment_date desc"), []),
    safe(list("Client Followup", [["client", "=", pid]], ["*"], 2000, "creation desc"), [])
  ]);

  const cleanPlans = plansBasic.filter(x => !isExcluded(x.branch));
  const b = {
    pid,
    patient: patient || { name: pid },
    plans: cleanPlans,
    users: {},
    transfers: [],
    sessions: sessions.filter(x => !isExcluded(x.branch)),
    invoices: invoices.filter(x => !isExcluded(x.branch)),
    appts: appts.filter(x => !isExcluded(x.branch)),
