function c3OpenProfilePhoto(url, name) {
  if (!url) return;
  const viewer = c3EnsureProfilePhotoViewer();
  const img = viewer.querySelector(".c3-photo-view-img");
  const label = viewer.querySelector(".c3-photo-view-name");
  img.src = url;
  img.alt = (name || "Client") + " profile photo";
  label.textContent = name || "Client photo";
  viewer.classList.add("is-open");
}

