      #c3ProfilePhotoUploader .c3-profile-upload-btn.primary{background:#1B6B3A;color:#fff;border-color:#1B6B3A}
      #c3ProfilePhotoUploader .c3-profile-upload-btn.camera{background:#F7F1DF;border-color:#E3C879;color:#7A5410}
      #c3ProfilePhotoUploader .c3-profile-camera-wrap{margin-top:14px;padding:12px;background:#f4f8f5;border:1px solid #d7e4da;border-radius:12px}
      #c3ProfilePhotoUploader .c3-profile-video{display:block;width:100%;max-height:300px;object-fit:cover;border-radius:10px;background:#111}
      #c3ProfilePhotoUploader .c3-profile-camera-actions{display:flex;gap:8px;margin-top:10px}
      #c3ProfilePhotoUploader .c3-profile-status{min-height:22px;margin-top:10px;font-size:13px;font-weight:700;color:#667085}
      #c3ProfilePhotoUploader .c3-profile-status.ok{color:#14833B}
      #c3ProfilePhotoUploader .c3-profile-status.err{color:#C62828}
      #c3ProfilePhotoUploader .c3-profile-save{width:100%;height:46px;margin-top:12px;border:0;border-radius:10px;background:#1B6B3A;color:#fff;font-size:14px;font-weight:800;cursor:pointer}
      #c3ProfilePhotoUploader .c3-profile-save:disabled{opacity:.45;cursor:not-allowed}
      @media(max-width:560px){#c3ProfilePhotoUploader .c3-profile-upload-actions{grid-template-columns:1fr}}
    `;
    document.head.appendChild(st);
  }

  viewer = document.createElement("div");
  viewer.id = "c3ProfilePhotoUploader";
  viewer.innerHTML = `
    <div class="c3-profile-upload-card" role="dialog" aria-modal="true" aria-label="Client profile photo">
      <div class="c3-profile-upload-head">
        <div><h3>📷 Client profile photo</h3><p class="c3-profile-upload-sub">This client has no completed Wellness Evaluation Session. Add a profile photo directly from this dashboard.</p></div>
        <button type="button" class="c3-profile-upload-close" aria-label="Close">×</button>
      </div>
      <div class="c3-profile-preview"><span>Choose a photo file or use the camera.</span><img alt="Profile photo preview"></div>
      <input type="file" class="c3-profile-file" accept="image/jpeg,image/png,image/webp,image/*" hidden>
      <div class="c3-profile-upload-actions">
        <button type="button" class="c3-profile-upload-btn c3-profile-file-btn">🖼️ Upload photo</button>
        <button type="button" class="c3-profile-upload-btn camera c3-profile-camera-btn">📷 Camera</button>
      </div>
      <div class="c3-profile-camera-wrap" hidden>
        <video class="c3-profile-video" autoplay playsinline></video>
        <canvas class="c3-profile-canvas" hidden></canvas>
        <div class="c3-profile-camera-actions">
          <button type="button" class="c3-profile-upload-btn primary c3-profile-capture-btn">Capture</button>
          <button type="button" class="c3-profile-upload-btn c3-profile-camera-cancel">Cancel</button>
        </div>
      </div>
      <div class="c3-profile-status"></div>
      <button type="button" class="c3-profile-save" disabled>Save profile photo</button>
    </div>`;
  document.body.appendChild(viewer);

  const fileInput = viewer.querySelector(".c3-profile-file");
  const preview = viewer.querySelector(".c3-profile-preview img");
  const placeholder = viewer.querySelector(".c3-profile-preview span");
  const status = viewer.querySelector(".c3-profile-status");
  const saveBtn = viewer.querySelector(".c3-profile-save");
  const video = viewer.querySelector(".c3-profile-video");
  const canvas = viewer.querySelector(".c3-profile-canvas");
  const cameraWrap = viewer.querySelector(".c3-profile-camera-wrap");

  const setStatus = (msg, tone) => {
    status.textContent = msg || "";
    status.className = "c3-profile-status" + (tone ? " " + tone : "");
  };
  const setPreview = blob => {
    c3ProfileUploadBlob = blob || null;
    if (!blob) {
      preview.removeAttribute("src");
      preview.style.display = "none";
      placeholder.style.display = "block";
      saveBtn.disabled = true;
      return;
    }
    preview.src = URL.createObjectURL(blob);
    preview.style.display = "block";
    placeholder.style.display = "none";
    saveBtn.disabled = false;
  };

  viewer.querySelector(".c3-profile-upload-close").onclick = c3CloseProfileUploader;
  viewer.addEventListener("click", e => { if (e.target === viewer) c3CloseProfileUploader(); });
  document.addEventListener("keydown", e => { if (e.key === "Escape" && viewer.classList.contains("is-open")) c3CloseProfileUploader(); });

  viewer.querySelector(".c3-profile-file-btn").onclick = () => fileInput.click();
  fileInput.onchange = () => {
    const file = fileInput.files && fileInput.files[0];
    if (!file) return;
    c3StopProfileCamera();
    if (!file.type || !file.type.startsWith("image/")) {
      fileInput.value = "";
      setStatus("Please choose an image file.", "err");
      return;
    }
    if (file.size > 10 * 1024 * 1024) {
      fileInput.value = "";
      setStatus("Photo must be below 10 MB.", "err");
      return;
    }
    setPreview(file);
    setStatus("Photo ready. Click Save profile photo.", "ok");
  };

  viewer.querySelector(".c3-profile-camera-btn").onclick = async () => {
    setStatus("Opening camera…");
    if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
      setStatus("Camera is not available in this browser.", "err");
      return;
    }
    try {
      c3StopProfileCamera();
      c3ProfileUploadStream = await navigator.mediaDevices.getUserMedia({ video: { facingMode: "user" }, audio: false });
      video.srcObject = c3ProfileUploadStream;
      cameraWrap.hidden = false;
      setStatus("Camera ready.");
    } catch (e) {
      setStatus("Camera not available: " + (e.message || e), "err");
    }
  };

  viewer.querySelector(".c3-profile-camera-cancel").onclick = () => {
    c3StopProfileCamera();
    setStatus("");
  };

  viewer.querySelector(".c3-profile-capture-btn").onclick = () => {
    const w = video.videoWidth || 640;
    const h = video.videoHeight || 480;
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext("2d");
    ctx.drawImage(video, 0, 0, w, h);
    canvas.toBlob(blob => {
      if (!blob) {
        setStatus("Unable to capture the photo.", "err");
        return;
      }
      setPreview(blob);
      c3StopProfileCamera();
      setStatus("Camera photo ready. Click Save profile photo.", "ok");
    }, "image/jpeg", .88);
  };

  saveBtn.onclick = async () => {
    if (!c3ProfileUploadBlob || !c3ProfileUploadBundle) return;
    const b = c3ProfileUploadBundle;
    saveBtn.disabled = true;
    setStatus("Uploading photo…");
    try {
      const fd = new FormData();
      const ext = c3ProfileUploadBlob.type === "image/png" ? "png" : c3ProfileUploadBlob.type === "image/webp" ? "webp" : "jpg";
      fd.append("file", c3ProfileUploadBlob, "client_profile_" + Date.now() + "." + ext);
      fd.append("is_private", "0");
      fd.append("folder", "Home/Attachments");
      fd.append("doctype", "Patient");
      fd.append("docname", b.pid);

      const res = await fetch("/api/method/upload_file", {
        method: "POST",
        credentials: "same-origin",
        headers: { "X-Frappe-CSRF-Token": csrf() },
        body: fd
      });
      let data = {};
      try { data = await res.json(); } catch (e) { /* ignore */ }
      const url = data && data.message && data.message.file_url;
      if (!res.ok || !url) throw new Error("Photo upload failed.");

      await call("frappe.client.set_value", {
        doctype: "Patient",
        name: b.pid,
        fieldname: "custom_client_photo",
        value: url
      });

      b.patient.custom_client_photo = url;
      b.portrait = url;
      b.lazy.portraitSource = "Patient.custom_client_photo";
      c3CloseProfileUploader();
      renderHero();
      toast("Profile photo saved", "ok");
    } catch (e) {
      console.error("[CLIENT-360] profile photo upload", e);
      saveBtn.disabled = false;
      setStatus(e.message || "Unable to save profile photo.", "err");
    }
  };

  return viewer;
}

function c3OpenProfileUploader(b, name) {
  if (!b) return;
  const viewer = c3EnsureProfileUploader();
  c3ProfileUploadBundle = b;
  c3ProfileUploadBlob = null;
  c3StopProfileCamera();
  const preview = viewer.querySelector(".c3-profile-preview img");
  const placeholder = viewer.querySelector(".c3-profile-preview span");
  const fileInput = viewer.querySelector(".c3-profile-file");
  const status = viewer.querySelector(".c3-profile-status");
  const saveBtn = viewer.querySelector(".c3-profile-save");
  const sub = viewer.querySelector(".c3-profile-upload-sub");
  if (preview) { preview.removeAttribute("src"); preview.style.display = "none"; }
  if (placeholder) placeholder.style.display = "block";
  if (fileInput) fileInput.value = "";
  if (status) { status.textContent = ""; status.className = "c3-profile-status"; }
  if (saveBtn) saveBtn.disabled = true;
  if (sub) sub.textContent = (name || "This client") + " — choose a photo file or use the camera, then save.";
  viewer.classList.add("is-open");
}

