/* ---------------- tabs ---------------- */
const TABS = [
  { k: "overview", i: "👤", l: "Overview" },
  { k: "billing", i: "🧾", l: "Billing & dues", link: "billing" },
  { k: "plans", i: "📋", l: "Plans", link: "service" },
  { k: "sessions", i: "💆", l: "Sessions", link: "service" },
  { k: "appointments", i: "📅", l: "Appointments", link: "appt" },
  { k: "followups", i: "📞", l: "Followups", link: "followup" },
  { k: "diet", i: "🥗", l: "Diet", link: "followup" },
  { k: "medical", i: "🩺", l: "Medical" },
  { k: "concerns", i: "🗣️", l: "Concerns" },
  { k: "documents", i: "📁", l: "Documents", link: "documents" },
  { k: "stock", i: "📦", l: "Stock", link: "stock" },
  { k: "conversions", i: "🔄", l: "Conversions", link: "conversions" },
  { k: "remarks", i: "📝", l: "Remarks" },
  { k: "messages", i: "💬", l: "Messages" }
];
function tabBadge(k) {
  const b = M.b, m = b && b.m;
  if (!m) return "";
  const map = {
    billing: [m.invCount, m.due.overdue ? "neg" : m.due.pending > 0 ? "warn" : ""],
    plans: [b.plans.length, m.overduePlans.length ? "neg" : m.behind.length ? "warn" : ""],
    sessions: [b.sessions.length, ""],
    appointments: [b.appts.length, m.nextAppt ? "ok" : ""],
    followups: [b.followups.length, m.overdueFu.length ? "warn" : ""],
    diet: [b.followups.filter(f => /diet/i.test(f.followup_type || "")).length, ""],
    medical: [m.med.flagged.length || "", m.med.flagged.length ? "neg" : ""]
  };
  const x = map[k];
  if (!x || x[0] === "" || x[0] === 0) return "";
  return `<span class="c3-tab-n ${x[1] ? "tone-" + x[1] : ""}">${x[0]}</span>`;
}
function renderTabs() {
  $("#c3Tabs").innerHTML = TABS.map(t => `<button type="button" role="tab" class="c3-tab${t.k === M.tab ? " is-on" : ""}" data-tab="${t.k}" aria-selected="${t.k === M.tab}">${t.i} ${t.l}${tabBadge(t.k)}</button>`).join("");
}
function tabToolbar(t) {
  if (!t || !t.link) return "";
  return `<div class="c3-tabbar"><span>${t.i} ${t.l} for this client</span><a class="c3-btn c3-btn-primary c3-btn-sm" href="${portalLink(t.link, M.pid)}" target="_blank" rel="noopener">Open in LIFE portal ↗</a></div>`;
}
const loaderHtml = txt => `<div class="c3-center"><div class="c3-loader"><span>LIFE</span></div><p>${esc(txt || "Loading…")}</p></div>`;
const emptyHtml = (ic, title, text) => `<div class="c3-center c3-empty"><div class="c3-state-ic">${ic}</div><h3>${esc(title)}</h3><p>${esc(text)}</p></div>`;

async function loadTab(k) {
  M.tab = k;
  $$(".c3-tab", $("#c3Tabs")).forEach(b => { const on = b.dataset.tab === k; b.classList.toggle("is-on", on); b.setAttribute("aria-selected", on); });
  const body = $("#c3MBody");
  const t = TABS.find(x => x.k === k);
  body.innerHTML = loaderHtml("Loading " + (t ? t.l.toLowerCase() : "") + "…");
  body.scrollTop = 0;
  const pid = M.pid;
  const R = { overview: tOverview, billing: tBilling, plans: tPlans, sessions: tSessions, appointments: tAppointments, followups: tFollowups,
    diet: tDiet, medical: tMedical, concerns: tConcerns, documents: tDocuments, stock: tStock, conversions: tConversions, remarks: tRemarks, messages: tMessages };
  try {
    const html = await R[k](M.b);
    if (M.pid !== pid || M.tab !== k) return;
    body.innerHTML = tabToolbar(t) + `<div class="c3-tab-body">${html}</div>`;
    if (R[k].after && !html.startsWith('<div class="c3-center c3-empty"')) R[k].after(body, M.b);
  } catch (e) {
    console.error("[CLIENT-360] tab " + k, e);
    if (M.pid === pid && M.tab === k) body.innerHTML = emptyHtml("⚠️", "This section could not load", e.message + " — switch tabs to retry.");
  }
}

async function openModal(pid) {
  if (!pid) return;
  closeDrawer(); hideLookup();
  const seq = ++M.seq;
  M.pid = pid; M.tab = "overview";
  $("#c3Modal").classList.add("is-open");
  $("#c3ModalOverlay").classList.add("is-open");
  document.body.style.overflow = "hidden";
  const row = S.all.find(r => r.id === pid) || {};
  $("#c3Hero").innerHTML = `<div class="c3-hero-main"><div class="c3-avatar"><div class="c3-avatar-in"><span>${esc(initials(row.name || pid))}</span></div></div>
    <div class="c3-hero-id"><div class="c3-brandline"><span class="c3-brand">LIFE</span><span>CLIENT - 360</span></div><h2>${esc(row.name || pid)}</h2><div class="c3-hero-meta"><span class="c3-chip">Building complete profile…</span></div></div>
    <div class="c3-hero-actions"><button type="button" class="c3-close" id="c3ModalClose" aria-label="Close">✕</button></div></div>`;
  $("#c3ModalClose").onclick = closeModal;
  $("#c3Tabs").innerHTML = "";
  $("#c3MBody").innerHTML = loaderHtml("Collecting plans, sessions, invoices, appointments and followups…");
  try {
    const b = M.cache[pid] || await loadBundle(pid);
    if (seq !== M.seq) return;
    M.cache[pid] = b; M.b = b;

    if (!b.lazy.referrals) c3SeedReferralsFromLoadedData(b);

    if (!(b.lazy.referrals.by || []).length) {
      console.info(
        "[CLIENT-360] No referral audit note found on loaded Sales Invoices for",
        pid
      );
    }

    /* Show the CLIENT-360 popup immediately. */
    renderHero();
    renderTabs();
    loadTab("overview");

    /* Heavy data continues in the background without blocking the popup. */
    c3HydrateBundleBackground(b, pid, seq);

    /*
     * Outgoing referred-client names are loaded separately first so they
     * can appear in the hero without waiting for the full referral scan.
     */
    c3LoadOutgoingReferralsFast(b, pid, seq);
    c3LoadReferralsBackground(b, pid, seq);

    resolvePortrait(b).then(url => {
      if (M.pid === pid && seq === M.seq) {
        if (url) b.portrait = url;
        renderHero();
      }
    });
  } catch (e) {
    console.error("[CLIENT-360] bundle", e);
    $("#c3MBody").innerHTML = emptyHtml("⚠️", "Client profile could not load", e.message);
  }
}
function closeModal() {
  M.seq++; M.pid = null;
  $("#c3Modal").classList.remove("is-open");
  $("#c3ModalOverlay").classList.remove("is-open");
  document.body.style.overflow = "";
}

/* ---------------- collapsible / reorderable sections ---------------- */
function sections(key, defs) {
  const order = pref(key + ".order") || [];
  const col = pref(key + ".collapsed") || {};
  const sorted = defs.filter(Boolean).slice().sort((a, c) => {
    const ia = order.indexOf(a.id), ic = order.indexOf(c.id);
    return (ia < 0 ? 999 : ia) - (ic < 0 ? 999 : ic);
  });
  return `<div class="c3-secs" data-secs="${esc(key)}">${sorted.map(d => `
    <section class="c3-sec${col[d.id] ? " is-collapsed" : ""}${d.wide ? " is-wide" : ""}" data-sec="${esc(d.id)}">
      <header class="c3-sec-h">
        <button type="button" class="c3-sec-title" data-sec-act="toggle" aria-expanded="${!col[d.id]}">
          <span class="c3-sec-ic">${d.icon}</span><span>${esc(d.title)}</span>${d.badge != null && d.badge !== "" ? `<span class="c3-sec-badge tone-${d.tone || "mute"}">${d.badge}</span>` : ""}
        </button>
        <div class="c3-sec-tools">
          <button type="button" data-sec-act="up" title="Move section up" aria-label="Move up">↑</button>
          <button type="button" data-sec-act="down" title="Move section down" aria-label="Move down">↓</button>
          <button type="button" data-sec-act="toggle" class="c3-chev" title="Collapse or expand" aria-label="Collapse or expand">⌃</button>
        </div>
      </header>
      <div class="c3-sec-b">${d.html}</div>
    </section>`).join("")}</div>`;
}
function wireSections(root) {
  $$("[data-secs]", root).forEach(wrap => {
    if (wrap.dataset.wired) return;
    wrap.dataset.wired = "1";
    const key = wrap.dataset.secs;
    wrap.addEventListener("click", e => {
      const btn = e.target.closest("[data-sec-act]");
      if (!btn || !wrap.contains(btn)) return;
      const sec = btn.closest(".c3-sec");
      const act = btn.dataset.secAct;
      if (act === "toggle") {
        sec.classList.toggle("is-collapsed");
        const c = pref(key + ".collapsed") || {};
        c[sec.dataset.sec] = sec.classList.contains("is-collapsed");
        pref(key + ".collapsed", c);
        $$("[data-sec-act=toggle].c3-sec-title", sec).forEach(x => x.setAttribute("aria-expanded", !c[sec.dataset.sec]));
        return;
      }
      if (act === "up" && sec.previousElementSibling) wrap.insertBefore(sec, sec.previousElementSibling);
      if (act === "down" && sec.nextElementSibling) wrap.insertBefore(sec.nextElementSibling, sec);
      sec.classList.add("is-moved");
      setTimeout(() => sec.classList.remove("is-moved"), 500);
      pref(key + ".order", $$(":scope > .c3-sec", wrap).map(x => x.dataset.sec));
    });
  });
}

