function c3SeedReferralsFromLoadedData(b) {
  if (!b || !b.lazy) return { by: [], fields: [], brought: [] };

  const r = {
    by: [],
    fields: (b.m && b.m.ref && b.m.ref.fields ? b.m.ref.fields : []).slice(),
    brought: []
  };

  ((b.m && b.m.ref && b.m.ref.by) || []).forEach(x => {
    const raw = String((x && x.value) || "").trim();
    if (!raw || c3ReferralGenericValue(raw)) return;
    c3UniqueReferralPush(r.by, {
      id: "",
      name: raw,
      source: "Patient",
      kind: ""
    });
  });

  (b.invoices || []).forEach(inv => {
    const clientRef = c3InvoiceReferralClient(inv);
    if (clientRef) {
      clientRef.kind = "client";
      c3UniqueReferralPush(r.by, clientRef);
    }

    /*
     * Read employee referral ONLY from the Billing audit note.
     * Do not use ref_practitioner/custom_referring_name here:
     * those belong to practitioner/consultant data.
     */
    const employeeRef = c3InvoiceReferralEmployee(inv);
    if (employeeRef) {
      c3UniqueReferralPush(r.by, employeeRef);
    }
  });

  c3PlanIncomingReferrals(b).forEach(x => {
    x.kind = "client";
    c3UniqueReferralPush(r.by, x);
  });

  b.lazy.referrals = r;
  return r;
}

/*
 * FAST OUTGOING REFERRAL LOOKUP
 * --------------------------------
 * Finds clients referred BY the currently opened client without waiting for
 * the complete referral/metadata scan.
 *
 * Billing stores client referrals in Sales Invoice.remarks like:
 *   Referred by client: Kavya Reddy (PATIENT-ID)
 *
 * As soon as a match is found, the hero is re-rendered so the referred
 * client name appears immediately in the top profile strip.
 */
function c3LoadOutgoingReferralsFast(b, pid, seq) {
  if (!b || !b.lazy) return Promise.resolve([]);
  if (b.lazy.outgoingReferralPromise) return b.lazy.outgoingReferralPromise;

  const patientName = String(
    (b.patient && b.patient.patient_name) || ""
  ).trim();

  const searchTerms = [
    pid ? `%Referred by client:%(${pid})%` : "",
    patientName ? `%Referred by client:${patientName}%` : ""
  ].filter(Boolean);

  b.lazy.outgoingReferralPromise = (async () => {
    const foundInvoices = [];
    const seenInvoice = new Set();

    for (const q of searchTerms) {
      const rows = await safe(
        list(
          "Sales Invoice",
          [
            ["docstatus", "!=", 2],
            ["remarks", "like", q]
          ],
          [
            "name",
            "patient",
            "patient_name",
            "posting_date",
            "creation",
            "remarks"
          ],
          500,
          "posting_date desc"
        ),
        []
      );

      (rows || []).forEach(inv => {
        if (!inv || !inv.name || seenInvoice.has(inv.name)) return;
        seenInvoice.add(inv.name);
        foundInvoices.push(inv);
      });
    }

    const currentRefs =
      b.lazy.referrals ||
      c3SeedReferralsFromLoadedData(b);

    const brought = currentRefs.brought || [];

    foundInvoices.forEach(inv => {
      if (
        !c3InvoiceWasReferredBy(
          inv,
          pid,
          patientName
        )
      ) {
        return;
      }

      const otherPid = String(inv.patient || "").trim();
      if (!otherPid || otherPid === pid) return;

      if (!brought.find(x => x.name === otherPid)) {
        brought.push({
          name: otherPid,
          patient_name:
            String(inv.patient_name || "").trim() ||
            otherPid,
          creation:
            inv.posting_date ||
            inv.creation ||
            "",
          _source: "Sales Invoice"
        });
      }
    });

    currentRefs.brought = brought;
    b.lazy.referrals = currentRefs;

    if (
      brought.length &&
      M.pid === pid &&
      seq === M.seq
    ) {
      renderHero();

      if (M.tab === "overview") {
        loadTab("overview");
      }
    }

    return brought;
  })().catch(err => {
    console.warn(
      "[CLIENT-360] fast outgoing referral lookup failed",
      err
    );
    return [];
  });

  return b.lazy.outgoingReferralPromise;
}

function c3LoadReferralsBackground(b, pid, seq) {
  if (!b || !b.lazy) return Promise.resolve(null);
  if (b.lazy.referralPromise) return b.lazy.referralPromise;

  b.lazy.referralPromise = loadReferrals(b)
    .then(r => {
      const previous =
        b.lazy.referrals ||
        { by: [], fields: [], brought: [] };

      const next =
        r ||
        { by: [], fields: [], brought: [] };

      /* Preserve anything the fast outgoing lookup already found. */
      (previous.by || []).forEach(x => {
        c3UniqueReferralPush(next.by, x);
      });

      (previous.brought || []).forEach(x => {
        if (
          x &&
          x.name &&
          !(next.brought || []).find(y => y.name === x.name)
        ) {
          next.brought.push(x);
        }
      });

      next.fields = Array.from(
        new Set([
          ...(next.fields || []),
          ...(previous.fields || [])
        ])
      );

      b.lazy.referrals = next;

      if (M.pid === pid && seq === M.seq) {
        renderHero();
        if (M.tab === "overview") loadTab("overview");
      }
      return next;
    })
    .catch(err => {
      console.warn("[CLIENT-360] background referral lookup failed", err);
      return b.lazy.referrals || null;
    });

  return b.lazy.referralPromise;
}

async function loadReferrals(b) {
  const r = { by: [], fields: (b.m.ref.fields || []).slice(), brought: [] };

  /* 1) Existing referral fields on Patient */
  (b.m.ref.by || []).forEach(x => {
    const raw = String((x && x.value) || "").trim();
    if (!raw || c3ReferralGenericValue(raw)) return;
    c3UniqueReferralPush(r.by, { id: "", name: raw, source: "Patient" });
  });

  /*
   * 2) PRIMARY LIVE SOURCE:
   * Billing saves "Referred by client: NAME (PATIENT-ID)" in Sales Invoice.remarks.
   */
  (b.invoices || []).forEach(inv => {
    const clientRef = c3InvoiceReferralClient(inv);
    if (clientRef) {
      clientRef.kind = "client";
      c3UniqueReferralPush(r.by, clientRef);
    }

    const employeeRef = c3InvoiceReferralEmployee(inv);
    if (employeeRef) {
      c3UniqueReferralPush(r.by, employeeRef);
    }
  });

  /* Compatibility with any older/custom Therapy Plan referral fields. */
  c3PlanIncomingReferrals(b).forEach(x => c3UniqueReferralPush(r.by, x));

  r.by = await c3ResolveReferralNames(r.by);

  const targetValues = [b.pid, b.patient && b.patient.patient_name].filter(Boolean);

  /*
   * 3) OUTGOING CLIENT REFERRALS:
   * Find invoices of other clients whose Billing remarks say this client
   * referred them. Search by exact Patient ID first because it is stored
   * inside parentheses in the live Billing referral note.
   */
  const outgoingInvoices = [];
  const seenOutgoingInvoices = new Set();

  const outgoingSearches = [
    b.pid ? `%Referred by client:%(${b.pid})%` : "",
    b.patient && b.patient.patient_name
      ? `%Referred by client:${b.patient.patient_name}%`
      : ""
  ].filter(Boolean);

  for (const q of outgoingSearches) {
    const rows = await safe(
      list(
        "Sales Invoice",
        [
          ["docstatus", "!=", 2],
          ["remarks", "like", q]
        ],
        ["name", "patient", "patient_name", "posting_date", "creation", "remarks"],
        500,
        "posting_date desc"
      ),
      []
    );

    rows.forEach(inv => {
      if (!inv || seenOutgoingInvoices.has(inv.name)) return;
      seenOutgoingInvoices.add(inv.name);
      outgoingInvoices.push(inv);
    });
  }

  outgoingInvoices.forEach(inv => {
    if (!c3InvoiceWasReferredBy(inv, b.pid, b.patient && b.patient.patient_name)) return;
    if (!inv.patient || inv.patient === b.pid) return;

    if (!r.brought.find(x => x.name === inv.patient)) {
      r.brought.push({
        name: inv.patient,
        patient_name: inv.patient_name || inv.patient,
        creation: inv.posting_date || inv.creation,
        _source: "Sales Invoice"
      });
    }
  });

  /*
   * 4) Optional legacy Patient referral fields.
   * IMPORTANT: query ONLY fields that actually exist in Patient metadata and
   * are filterable scalar fields. The previous script tried document keys /
   * guessed field names and Frappe returned HTTP 417 for invalid filters.
   */
  const patientMeta = await safe(metaFields("Patient"), null);
  const refPatientFields = (patientMeta || [])
    .filter(f => {
      if (!f || !f.fieldname) return false;
      const key = lc((f.fieldname || "") + " " + (f.label || ""));
      const looksReferral = /(referr|refered|referred|reference|ref by|ref_by)/.test(key);
      const scalar = ["Link", "Data", "Dynamic Link", "Small Text"].includes(f.fieldtype);
      return looksReferral && scalar;
    })
    .map(f => f.fieldname)
    .slice(0, 5);

  for (const field of refPatientFields) {
    const rows = await safe(
      list(
        "Patient",
        [[field, "in", targetValues]],
        ["name", "patient_name", "sex", "creation"],
        200
      ),
      []
    );

    rows.forEach(x => {
      if (x.name !== b.pid && !r.brought.find(y => y.name === x.name)) {
        r.brought.push(x);
      }
    });
  }

  /*
   * 5) Optional legacy Therapy Plan referral fields.
   * Never query guessed fields. Only query fields positively confirmed by
   * Therapy Plan metadata. Current Billing stores client-referral audit data
   * in Sales Invoice.remarks, handled above.
   */
  const planMeta = await safe(metaFields("Therapy Plan"), null);
  const refPlanFields = (planMeta || [])
    .filter(f => {
      if (!f || !f.fieldname) return false;
      const key = lc((f.fieldname || "") + " " + (f.label || ""));
      const looksReferral = /(referr|refered|referred|reference|ref by|ref_by)/.test(key);
      const looksClient = /(client|patient)/.test(key);
      const scalar = ["Link", "Data", "Dynamic Link"].includes(f.fieldtype);
      return looksReferral && looksClient && scalar;
    })
    .map(f => f.fieldname)
    .slice(0, 5);

  const referredPatientIds = [];

  for (const field of refPlanFields) {
    const plans = await safe(
      list(
        "Therapy Plan",
        [[field, "in", targetValues]],
        ["name", "patient", "patient_name", "start_date", "creation"],
        500,
        "creation desc"
      ),
      []
    );

    plans.forEach(plan => {
      const otherPid = String(plan.patient || "").trim();
      if (
        otherPid &&
        otherPid !== b.pid &&
        !referredPatientIds.includes(otherPid)
      ) {
        referredPatientIds.push(otherPid);
      }
    });
  }

  if (referredPatientIds.length) {
    const patients = await inChunks(
      referredPatientIds,
      ids => list(
        "Patient",
        [["name", "in", ids]],
        ["name", "patient_name", "sex", "creation"],
        500
      ),
      80
    );

    patients.forEach(x => {
      if (x.name !== b.pid && !r.brought.find(y => y.name === x.name)) {
        r.brought.push(x);
      }
    });
  }

  b.lazy.referrals = r;
  return r;
}

