      html: `<div class="c3-filters" data-inv-filters>${["all", "unpaid", "partial", "overdue", "paid"].map((f, i) => `<button type="button" class="c3-fbtn${i ? "" : " is-on"}" data-f="${f}">${f === "all" ? "All" : INV_STATE[f][1]} (${f === "all" ? invs.length : invs.filter(x => invClass(x) === f).length})</button>`).join("")}</div>
        <div class="c3-inv-grid-list" data-inv-list>${invs.map(i => `<div data-cls="${invClass(i)}">${invoiceCard(i)}</div>`).join("") || `<div class="c3-empty-sm">No invoices.</div>`}</div>` },
    { id: "payments", icon: "💳", title: "Payments received", badge: pays.length, wide: true,
      html: pays.length ? `<div class="c3-bars">${Object.entries(modes).sort((a, c) => c[1] - a[1]).map(([k, v]) => `<div class="c3-bar"><span class="c3-bar-l">${esc(k)}</span><span class="c3-bar-t"><i style="width:${v / maxMode * 100}%"></i></span><b>${money(v)}</b></div>`).join("")}</div>
        <div class="c3-table-wrap"><table class="c3-mini-table"><thead><tr><th>Date</th><th>Receipt</th><th>Mode</th><th>Branch</th><th class="t-r">Amount</th></tr></thead><tbody>
        ${pays.map(x => `<tr><td>${fdate(x.posting_date)}</td><td>${esc(x.name)}</td><td>${esc(x.mode_of_payment || "—")}</td><td>${esc(x.branch || "—")}</td><td class="t-r tone-ok">${money(peAmount(x))}</td></tr>`).join("")}</tbody></table></div>`
        : `<div class="c3-empty-sm">No payment entries linked to this client's customer record.</div>` }
  ]);
}
tBilling.after = body => {
  wireSections(body);
  body.addEventListener("click", e => {
