    $$("[data-inv-list] > [data-cls]", body).forEach(x => { x.hidden = !(f.dataset.f === "all" || x.dataset.cls === f.dataset.f || (f.dataset.f === "unpaid" && x.dataset.cls === "overdue")); });
  });
};
async function loadPayments(b) {
  const p = b.patient, f = ["name", "posting_date", "mode_of_payment", "party", "party_name", "branch", "base_received_amount", "received_amount", "paid_amount", "reference_no", "docstatus"];
  let rows = [];
  if (p.customer) rows = await safe(list("Payment Entry", [["party", "=", p.customer], ["docstatus", "=", 1], ["payment_type", "=", "Receive"]], f, 2000, "posting_date desc"), []);
  if (!rows.length && p.patient_name) rows = await safe(list("Payment Entry", [["party_name", "=", p.patient_name], ["docstatus", "=", 1], ["payment_type", "=", "Receive"]], f, 2000, "posting_date desc"), []);
  b.lazy.payments = rows.filter(x => !isExcluded(x.branch));
  return b.lazy.payments;
}

