  const weights = s.filter(x => num(x.before_weight) > 0).sort((a, c) => String(a.start_date).localeCompare(String(c.start_date)));
  const wFirst = weights.length ? num(weights[0].before_weight) : 0;
  const wLast = weights.length ? (num(weights[weights.length - 1].after_weight) || num(weights[weights.length - 1].before_weight)) : 0;
  const wDiff = Math.round((wLast - wFirst) * 10) / 10;
  return `<div class="c3-kpis">
