      ${kpi("📆", "Avg / month", b.m.avgMonthly.toFixed(1), b.m.consistency === "Irregular" ? "warn" : "ok")}
      ${weights.length > 1 ? kpi("⚖️", "Weight change", (wDiff > 0 ? "+" : "") + wDiff + " kg", wDiff < 0 ? "ok" : wDiff > 0 ? "neg" : "") : kpi("🕒", "Last session", fdate(b.m.last))}
