        <div class="c3-grid c3-g2"><div class="c3-field f-purple"><small>⏱ Duration</small><b>${esc(x.duration || "—")} min</b></div><div class="c3-field f-teal"><small>🏢 Branch</small><b>${esc(x.branch || "—")}</b></div></div>
