/* ---------------- APPOINTMENTS ---------------- */
async function tAppointments(b) {
  const slotSeconds = v => { const parts = String(v || "0:0:0").split(":").map(num); return parts[0] * 3600 + (parts[1] || 0) * 60 + (parts[2] || 0); };
  const a = b.appts.slice().sort((x, y) => d10(y.appointment_date).localeCompare(d10(x.appointment_date)) || slotSeconds(y.appointment_time) - slotSeconds(x.appointment_time));
  if (!a.length) return emptyHtml("📅", "No appointments", "Book the next visit from the Book appointment button.");
  const statuses = ["All", ...new Set(a.map(x => x.status || "Unknown"))];
  const up = a.filter(x => d10(x.appointment_date) >= b.m.t && !["cancelled", "no show"].includes(lc(x.status))).length;
  const noShow = a.filter(x => lc(x.status) === "no show").length;
  return `<div class="c3-kpis">${kpi("📅", "Total", a.length)}${kpi("⏭️", "Upcoming", up, up ? "ok" : "")}${kpi("✅", "Closed / checked out", a.filter(x => ["closed", "checked out"].includes(lc(x.status))).length, "ok")}
      ${kpi("🙈", "No show", noShow, noShow ? "neg" : "")}${kpi("✕", "Cancelled", a.filter(x => lc(x.status) === "cancelled").length, "warn")}</div>
    <div class="c3-filters" data-appt-f>${statuses.map((s, i) => `<button type="button" class="c3-fbtn${i ? "" : " is-on"}" data-f="${esc(s)}">${esc(s)} (${s === "All" ? a.length : a.filter(x => (x.status || "Unknown") === s).length})</button>`).join("")}</div>
    <div class="c3-cards c3-c4" data-appt-grid></div>
    <div class="c3-pager-sm" data-appt-pager></div>`;
}
tAppointments.after = (body, b) => {
  let f = "All", page = 1;
  const PS = 16, t = b.m.t;
  const slotSeconds = v => { const p = String(v || "0:0:0").split(":").map(num); return p[0] * 3600 + (p[1] || 0) * 60 + (p[2] || 0); };
  const sortedAppts = b.appts.slice().sort((x,y) => d10(y.appointment_date).localeCompare(d10(x.appointment_date)) || slotSeconds(y.appointment_time)-slotSeconds(x.appointment_time));
  const draw = () => {
    const rows = sortedAppts.filter(x => f === "All" || (x.status || "Unknown") === f);
    const pages = Math.max(1, Math.ceil(rows.length / PS));
    page = Math.min(page, pages);
    $("[data-appt-grid]", body).innerHTML = rows.slice((page - 1) * PS, page * PS).map(x => {
      const s = lc(x.status), d = d10(x.appointment_date);
      const tone = ["closed", "checked out"].includes(s) ? "ok" : s === "cancelled" ? "warn" : s === "no show" ? "neg" : d >= t ? "info" : "mute";
      return `<article class="c3-card c3-accent tone-${tone}">
        <header class="c3-card-h"><div><b>${d === t ? "📍 Today" : d > t ? "⏭️ " + fdate(d) : fdate(d)}</b><small>🕐 ${ftime(x.appointment_time) || "—"}</small></div><span class="c3-pill tone-${tone}">${esc(x.status || "—")}</span></header>
        <div class="c3-field f-green"><small>📌 Type</small><b>${esc(x.appointment_type || "General")}</b></div>
        <div class="c3-field f-blue"><small>💆 Therapy</small><b>${esc(x.therapy_type1 || x.therapy_type || "—")}</b></div>
        <div class="c3-field"><small>🩺 Concern</small><b>${esc(x.concern || "—")}</b></div>
        <div class="c3-grid c3-g2">
          <div class="c3-field f-amber"><small>👩‍⚕️ Practitioner</small><b>${esc(x.practitioner_name || x.practitioner || "—")}</b></div>
          <div class="c3-field f-teal"><small>🏢 Branch</small><b>${esc(x.branch || "—")}</b></div>
        </div>
        ${x.call_back_status ? `<div class="c3-mini tone-warn">📞 Confirmation: ${esc(x.call_back_status)}</div>` : ""}
        ${x.service_room || x.service_unit ? `<div class="c3-mini">🚪 ${esc([x.service_room, x.service_unit].filter(Boolean).join(" / "))}</div>` : ""}
      </article>`;
    }).join("");
    $("[data-appt-pager]", body).innerHTML = pages > 1 ? `<button type="button" class="c3-btn c3-btn-sm" data-p="-1" ${page === 1 ? "disabled" : ""}>Previous</button><span>Page ${page} of ${pages}</span><button type="button" class="c3-btn c3-btn-sm" data-p="1" ${page === pages ? "disabled" : ""}>Next</button>` : "";
  };
  body.addEventListener("click", e => {
    const fb = e.target.closest("[data-appt-f] .c3-fbtn");
    if (fb) { f = fb.dataset.f; page = 1; $$("[data-appt-f] .c3-fbtn", body).forEach(x => x.classList.toggle("is-on", x === fb)); draw(); return; }
    const pb = e.target.closest("[data-appt-pager] [data-p]");
    if (pb) { page += Number(pb.dataset.p); draw(); }
