/* ---------------- FOLLOWUPS ---------------- */
function fuType(t) {
  const s = lc(t);
  if (s.includes("appointment")) return ["blue", "📅"];
  if (s.includes("diet")) return ["green", "🥗"];
  if (/pending|due|balance|payment/.test(s)) return ["orange", "₹"];
  if (s.includes("feedback")) return ["amber", "⭐"];
  if (s.includes("unjoined")) return ["red", "👤"];
  if (s.includes("existing")) return ["teal", "📞"];
  if (/treatment|therapy/.test(s)) return ["purple", "🩺"];
  if (s.includes("maintenance")) return ["slate", "🔄"];
  if (/complaint|concern/.test(s)) return ["red", "🗣️"];
  return ["slate", "📌"];
}
function followupCards(rows, t) {
  return rows.map(r => {
    const [col, ic] = fuType(r.followup_type);
    const st = lc(r.status), done = ["completed", "closed", "done"].includes(st);
    const next = d10(r.next_followup_date);
    const late = next && next < t && !done && st !== "cancelled";
    return `<article class="c3-card c3-fu f-${col}${late ? " is-late" : ""}" data-type="${esc(r.followup_type || "Other")}">
      <header class="c3-card-h"><div><span class="c3-pill c3-fu-type">${ic} ${esc(r.followup_type || "Followup")}</span><small>📅 ${fdate(r.followup_date || r.creation)} ${r.followup_time ? ftime(r.followup_time) : ""}</small></div>
        <span class="c3-pill tone-${done ? "ok" : st.includes("not reachable") ? "neg" : "warn"}">${esc(r.status || "Open")}</span></header>
      <p class="c3-fu-remark">${esc(r.remarks || r.client_response || "No remarks recorded.")}</p>
      ${r.client_response && r.remarks ? `<p class="c3-fu-resp">💬 Client said: ${esc(r.client_response)}</p>` : ""}
      <div class="c3-grid c3-g3">
        ${kv("By", esc(r.employee_name || r.employee || r.followup_by || "—"))}
        ${kv("Channel", esc(r.contact_channel || "—"))}
        ${kv("Outcome", esc(r.call_outcome || "—"))}
        ${kv("Priority", esc(r.priority || "Normal"), lc(r.priority) === "high" ? "is-neg" : "")}
        ${kv("Branch", esc(r.branch || "—"))}
        ${kv("Next followup", next ? `<span class="${late ? "tone-neg" : ""}">${fdate(next)}${late ? " ⏰ due" : ""}</span>` : "—")}
      </div>
      ${r.linked_invoice || r.linked_appointment || r.linked_therapy_plan ? `<div class="c3-mini">🔗 ${esc([r.linked_invoice, r.linked_appointment, r.linked_therapy_plan].filter(Boolean).join(", "))}</div>` : ""}
    </article>`;
  }).join("");
}
async function tFollowups(b) {
  const rows = b.followups;
  if (!rows.length) return emptyHtml("📞", "No followups", "Followups logged for this client will show here with full call history.");
  const t = b.m.t;
