};

/* ---------------- generic linked records (concerns / diet) ---------------- */
async function linkedRecords(doctypes, b) {
  const out = [];
  for (const dt of doctypes) {
    const fields = await metaFields(dt);
    if (!fields) continue;
    const pl = fields.find(f => f.fieldtype === "Link" && f.options === "Patient") ||
               fields.find(f => ["client", "patient", "custom_client", "custom_patient"].includes(f.fieldname));
    const cl = !pl && b.patient.customer ? fields.find(f => f.fieldtype === "Link" && f.options === "Customer") : null;
    const lf = pl || cl;
    if (!lf) continue;
    const rows = await safe(list(dt, [[lf.fieldname, "=", pl ? b.pid : b.patient.customer]], ["*"], 300, "creation desc"), []);
    rows.forEach(r => out.push({ doctype: dt, fields, row: r }));
  }
  return out;
}
function recordCard(x) {
  const r = x.row, lab = {};
  x.fields.forEach(f => { lab[f.fieldname] = f.label || f.fieldname; });
  const pick = keys => keys.map(k => r[k]).find(v => v && typeof v === "string");
  const title = pick(["subject", "title", "complaint_title", "concern", "complaint_type", "concern_type", "category", "issue_type", "diet_plan_name", "plan_name"]) || r.name;
  const status = pick(["status", "workflow_state", "resolution_status"]) || "";
  const date = pick(["complaint_date", "concern_date", "date", "opening_date", "posting_date", "from_date"]) || r.creation;
  const text = pick(["description", "details", "complaint_details", "concern_details", "remarks", "notes"]);
  const resolution = pick(["resolution", "resolution_details", "action_taken", "closing_remarks"]);
  const skip = new Set(["name", "owner", "modified_by", "creation", "modified", "docstatus", "idx", "doctype", "patient", "client", "customer", "naming_series", "amended_from"]);
  const extras = x.fields.filter(f => ["Data", "Select", "Link", "Date", "Currency", "Int", "Float"].includes(f.fieldtype) && !skip.has(f.fieldname) && r[f.fieldname] != null && r[f.fieldname] !== "" && typeof r[f.fieldname] !== "object").slice(0, 8);
  const done = /(closed|resolved|completed|done)/i.test(status);
  const sev = pick(["priority", "severity"]) || "";
  return `<article class="c3-card c3-accent tone-${done ? "ok" : /high|critical|urgent/i.test(sev) ? "neg" : "warn"}">
    <header class="c3-card-h"><div><b>${esc(title)}</b><small>${esc(x.doctype)} ${esc(r.name)}, ${fdate(date)}</small></div>${status ? `<span class="c3-pill tone-${done ? "ok" : "warn"}">${esc(status)}</span>` : ""}</header>
    ${text ? `<p class="c3-fu-remark">${esc(stripHtml(text))}</p>` : ""}
    ${resolution ? `<p class="c3-fu-resp">✅ ${esc(stripHtml(resolution))}</p>` : ""}
    <div class="c3-grid c3-g3">${extras.map(f => kv(esc(lab[f.fieldname]), esc(f.fieldtype === "Date" ? fdate(r[f.fieldname]) : r[f.fieldname]))).join("")}</div>
  </article>`;
}

