/* ---------------- DOCUMENTS ---------------- */
const fileType = u => { const c = lc(String(u).split("?")[0]); return /\.(jpe?g|png|gif|webp|bmp|svg|heic|heif)$/.test(c) ? "image" : /\.pdf$/.test(c) ? "pdf" : /\.(mp4|mov|m4v|webm|avi|3gp)$/.test(c) ? "video" : /\.(docx?|xlsx?|csv|txt|pptx?)$/.test(c) ? "doc" : "file"; };
function docCategory(f) {
  const t = lc([f.name, f.field, f.doctype].join(" ")).replace(/[_\-]+/g, " ");
  if (/aadh?aa?r/.test(t)) return ["id", "🪪 Aadhaar"];
  if (/pan ?card/.test(t)) return ["id", "💳 PAN"];
  if (/before|pre treatment/.test(t) && f.type === "image") return ["before", "📷 Before"];
  if (/after|post treatment/.test(t) && f.type === "image") return ["after", "📸 After"];
  if (/pd ?form|pd image|pd document/.test(t)) return ["pd", "📝 PD form"];
  if (/consent/.test(t)) return ["consent", "✍️ Consent"];
  if (/loan|declaration/.test(t)) return ["loan", "🎥 Loan"];
  if (/screenshot|receipt|proof/.test(t)) return ["payment", "🧾 Payment proof"];
  if (f.type === "image") return ["image", "🖼️ Image"];
  if (f.type === "video") return ["video", "🎬 Video"];
  if (f.type === "pdf" || f.type === "doc") return ["doc", "📄 Document"];
  return ["other", "📎 Other"];
}
async function loadDocuments(b) {
  const files = [], seen = new Set();
  const push = (url, name, doctype, docname, field, modified) => {
    if (!url || doctype === "Sales Invoice") return;
    const key = String(url).split("?")[0];
    if (seen.has(key)) return;
    seen.add(key);
    const f = { url, name: name || decodeURIComponent(key.split("/").pop() || "File"), doctype, docname, field: field || "", modified, type: fileType(url) };
    const c = docCategory(f); f.cat = c[0]; f.catLabel = c[1];
    files.push(f);
  };
  const isUrl = v => typeof v === "string" && /^(\/files\/|\/private\/files\/|https?:\/\/)/.test(v);
  const scan = (doctype, doc, depth, path) => {
    if (!doc || depth > 2) return;
    Object.keys(doc).forEach(k => {
      const v = doc[k];
      if (Array.isArray(v)) v.forEach(r => scan(doctype, Object.assign({ name: doc.name, modified: doc.modified }, r), depth + 1, k));
      else if (isUrl(v) && /(image|photo|attach|file|document|before|after|consent|pd|video|loan|aadh|pan|screenshot|receipt|proof)/i.test(k)) push(v, null, doctype, doc.name, (path ? path + "." : "") + k, doc.modified);
    });
  };
  scan("Patient", b.patient, 0, "");
  const pays = b.lazy.payments || await loadPayments(b);
  const groups = [["Patient", [b.pid]], ["Therapy Plan", b.plans.map(x => x.name)], ["Therapy Session", b.sessions.map(x => x.name)],
    ["Patient Appointment", b.appts.map(x => x.name)], ["Payment Entry", pays.map(x => x.name)], ["Client Followup", b.followups.map(x => x.name)]];
  for (const [dt, names] of groups) {
    if (!names.length) continue;
    const rows = await inChunks(names, c => safe(list("File", [["attached_to_doctype", "=", dt], ["attached_to_name", "in", c]], ["name", "file_name", "file_url", "attached_to_name", "attached_to_field", "modified"], 5000), []));
    rows.forEach(r => push(r.file_url, r.file_name, dt, r.attached_to_name, r.attached_to_field, r.modified));
  }
  const peDocs = await pooled(pays.slice(0, 40), 6, x => getDoc("Payment Entry", x.name));
  peDocs.forEach(d => scan("Payment Entry", d, 0, ""));
  files.sort((a, c) => String(c.modified).localeCompare(String(a.modified)));
  b.lazy.docs = files;
  return files;
}
async function tDocuments(b) {
  const files = b.lazy.docs || await loadDocuments(b);
  if (!files.length) return emptyHtml("📁", "No documents", "Before/after photos, consent forms, IDs and payment proofs attached anywhere on this client will collect here.");
  const cats = {};
  files.forEach(f => { cats[f.catLabel] = (cats[f.catLabel] || 0) + 1; });
  return `<div class="c3-filters" data-doc-f><button type="button" class="c3-fbtn is-on" data-f="">📁 All (${files.length})</button>${Object.entries(cats).map(([k, n]) => `<button type="button" class="c3-fbtn" data-f="${esc(k)}">${esc(k)} (${n})</button>`).join("")}
      <input type="search" class="c3-input c3-doc-search" placeholder="Search file or record" data-doc-q></div>
    <div class="c3-docs" data-doc-grid>${files.map(f => `
      <article class="c3-doc" data-cat="${esc(f.catLabel)}" data-q="${esc(lc([f.name, f.doctype, f.docname, f.catLabel].join(" ")))}">
        <a class="c3-doc-prev" href="${esc(f.url)}" target="_blank" rel="noopener">
          ${f.type === "image" ? `<img src="${esc(f.url)}" alt="${esc(f.name)}" loading="lazy">` : f.type === "video" ? `<video src="${esc(f.url)}#t=0.1" preload="metadata" muted playsinline></video><span class="c3-play">▶</span>` : `<span class="c3-doc-ic">${f.type === "pdf" ? "📕" : "📄"}</span>`}
        </a>
        <div class="c3-doc-b"><span class="c3-pill tone-info">${esc(f.catLabel)}</span><b title="${esc(f.name)}">${esc(f.name)}</b><small>${esc(f.doctype)} ${esc(f.docname || "")}, ${fdate(f.modified)}</small></div>
        <div class="c3-doc-act"><a href="${esc(f.url)}" target="_blank" rel="noopener">👁 View</a><a href="${esc(f.url)}" download>⬇ Download</a></div>
      </article>`).join("")}</div>
    <div class="c3-empty-sm" data-doc-none hidden>No files match.</div>`;
}
tDocuments.after = body => {
  let cat = "", q = "";
  const apply = () => {
    let n = 0;
    $$("[data-doc-grid] > .c3-doc", body).forEach(d => { const ok = (!cat || d.dataset.cat === cat) && (!q || d.dataset.q.includes(q)); d.hidden = !ok; if (ok) n++; });
    $("[data-doc-none]", body).hidden = n > 0;
  };
  body.addEventListener("click", e => {
    const fb = e.target.closest("[data-doc-f] .c3-fbtn");
    if (!fb) return;
    cat = fb.dataset.f;
    $$("[data-doc-f] .c3-fbtn", body).forEach(x => x.classList.toggle("is-on", x === fb));
    apply();
  });
  $("[data-doc-q]", body).addEventListener("input", e => { q = lc(e.target.value); apply(); });
};

