async function tStock(b) {
  if (!b.lazy.stock) {
    const mrF = ["name", "transaction_date", "creation", "owner", "docstatus", "material_request_type", "custom_stock_request_type", "custom_stock_request_status", "custom_client_name", "set_warehouse"];
    const [byId, byName, se] = await Promise.all([
      safe(list("Material Request", [["custom_client", "=", b.pid]], mrF, 300), []),
      safe(list("Material Request", [["custom_client_name", "=", b.patient.patient_name || "~"]], mrF, 300), []),
      safe(call(CFG.STOCK_API, { patient: b.pid }), [])
    ]);
    const mm = {};
    [...byId, ...byName].forEach(x => { mm[x.name] = x; });
    const docs = (await pooled(Object.keys(mm), 5, n => getDoc("Material Request", n))).filter(Boolean);
    const seMap = {};
    (se || []).forEach(r => { if (!r.stock_entry) return; (seMap[r.stock_entry] = seMap[r.stock_entry] || { h: r, items: [] }).items.push(r); });
    b.lazy.stock = { mr: docs.sort((a, c) => String(c.transaction_date || c.creation).localeCompare(String(a.transaction_date || a.creation))), se: Object.values(seMap) };
  }
  const { mr, se } = b.lazy.stock;
  const mrQty = mr.reduce((s, d) => s + (d.items || []).reduce((t, i) => t + num(i.qty), 0), 0);
  const seQty = se.reduce((s, e) => s + e.items.reduce((t, i) => t + num(i.qty), 0), 0);
  const mrCards = mr.map(d => {
    const st = d.workflow_state || d.custom_stock_request_status || (Number(d.docstatus) === 1 ? "Submitted" : Number(d.docstatus) === 2 ? "Cancelled" : "Draft");
    const tone = /cancel|reject/i.test(st) ? "neg" : /release|approve|submit|issued/i.test(st) ? "ok" : "warn";
    return `<article class="c3-card c3-accent tone-${tone}"><header class="c3-card-h"><div><b>📋 ${esc(d.name)}</b><small>${fdate(d.transaction_date || d.creation)}, ${esc(d.set_warehouse || "—")}</small></div><span class="c3-pill tone-${tone}">${esc(st)}</span></header>
      <div class="c3-mini">${esc((d.custom_stock_request_type === "Special Material Request" ? "Consumable Request" : d.custom_stock_request_type) || d.material_request_type || "Material Request")}</div>
      <div class="c3-chips">${(d.items || []).map(i => `<span class="c3-chip">${esc(i.item_name || i.item_code)} <b>${num(i.qty)} ${esc(i.uom || "")}</b></span>`).join("") || `<span class="c3-chip">No items</span>`}</div></article>`;
  }).join("");
  const seCards = se.map(e => {
    const ds = Number(e.h.docstatus), tone = ds === 1 ? "ok" : ds === 2 ? "neg" : "warn";
    return `<article class="c3-card c3-accent tone-${tone}"><header class="c3-card-h"><div><b>📦 ${esc(e.h.stock_entry)}</b><small>${fdate(e.h.posting_date)}, ${esc(e.h.purpose || e.h.stock_entry_type || "Stock entry")}</small></div><span class="c3-pill tone-${tone}">${ds === 1 ? "Submitted" : ds === 2 ? "Cancelled" : "Draft"}</span></header>
      ${e.items.map(i => `<div class="c3-stock-item"><b>${esc(i.item_name || i.item_code)}</b><span>Qty <b>${num(i.qty)}</b> ${esc(i.uom || "")}</span><small>🏬 ${esc(i.s_warehouse || "—")} → 🏥 ${esc(i.t_warehouse || "Issued")}</small>
        ${num(i.custom_released_qty) || num(i.custom_received_qty) ? `<small>🚚 Released ${num(i.custom_released_qty)}, ✅ received ${num(i.custom_received_qty)}${num(i.custom_missing_qty) ? `, <span class="tone-neg">missing ${num(i.custom_missing_qty)}</span>` : ""}</small>` : ""}</div>`).join("")}</article>`;
  }).join("");
  return `<div class="c3-kpis">${kpi("📋", "Material requests", mr.length)}${kpi("🧴", "Requested qty", mrQty)}${kpi("📦", "Stock entries", se.length)}${kpi("📊", "Issued qty", seQty)}</div>
    <div class="c3-split"><section><h4 class="c3-h4">📋 Material requests</h4>${mrCards || `<div class="c3-empty-sm">No material requests for this client.</div>`}</section>
    <section><h4 class="c3-h4">📦 Stock entries</h4>${seCards || `<div class="c3-empty-sm">No stock issued for this client.</div>`}</section></div>`;
}

